import struct, io

CT={0:'STOP',1:'TRUE',2:'FALSE',3:'BYTE',4:'I16',5:'I32',6:'I64',7:'DOUBLE',8:'BINARY',9:'LIST',10:'SET',11:'MAP',12:'STRUCT'}

class R:
    def __init__(self,data): self.d=data; self.p=0
    def byte(self): b=self.d[self.p]; self.p+=1; return b
    def varint(self):
        shift=0; result=0
        while True:
            b=self.byte(); result|= (b&0x7f)<<shift
            if not (b&0x80): break
            shift+=7
        return result
    def zigzag(self):
        n=self.varint(); return (n>>1) ^ -(n&1)
    def binary(self):
        ln=self.varint(); v=self.d[self.p:self.p+ln]; self.p+=ln; return v

def read_elem(r, etype):
    if etype in (5,6,4,3): # i32/i64/i16/byte treat?
        # byte in compact is single signed byte? but for enums i32
        return r.zigzag()
    if etype==8:
        return r.binary()
    if etype==12:
        return read_struct(r)
    raise Exception(f"elem type {etype} at {r.p}")

def read_val(r, ctype, field_name=None):
    if ctype==1: return True
    if ctype==2: return False
    if ctype==3:
        b=r.byte(); return b-256 if b>127 else b
    if ctype in (4,5,6):
        return r.zigzag()
    if ctype==7:
        v=struct.unpack('<d', r.d[r.p:r.p+8])[0]; r.p+=8; return v
    if ctype==8:
        return r.binary()
    if ctype==9 or ctype==10:
        hb=r.byte(); size=hb>>4; etype=hb&0x0f
        if size==15: size=r.varint()
        return [read_elem(r,etype) for _ in range(size)]
    if ctype==11:
        size=r.varint()
        if size==0: return []
        hb=r.byte(); kt=hb>>4; vt=hb&0x0f
        return [(read_elem(r,kt),read_elem(r,vt)) for _ in range(size)]
    if ctype==12:
        return read_struct(r)
    raise Exception(f"ctype {ctype}")

def read_struct(r):
    out={}
    last=0
    while True:
        b=r.byte()
        if b==0: break
        delta=b>>4; ctype=b&0x0f
        if delta==0:
            fid=r.zigzag()
        else:
            fid=last+delta
        last=fid
        out[fid]=read_val(r,ctype,fid)
    return out

def parse_footer(path):
    data=open(path,'rb').read()
    assert data[:4]==b'PAR1' and data[-4:]==b'PAR1', data[:4]
    flen=struct.unpack('<I', data[-8:-4])[0]
    footer=data[len(data)-8-flen:len(data)-8]
    r=R(footer)
    meta=read_struct(r)
    return data,meta

def decode_schemas(meta):
    return meta.get(2,[])
if __name__=="__main__":
    import sys, pprint
    data,meta=parse_footer(sys.argv[1] if len(sys.argv)>1 else "assets/alltypes_plain.parquet")
    print("version",meta.get(1),"num_rows",meta.get(3),"created",meta.get(6))
