{"command":"cat > src/thrift.rs <<'RS'
// Thrift compact protocol reader (subset needed for Parquet metadata / page headers)
#[derive(Debug, Clone, PartialEq)]
pub enum TVal {
    Bool(bool),
    Byte(i8),
    I64(i64),
    Double(f64),
    Binary(Vec<u8>),
    List(Vec<TVal>),
    Struct(Vec<(i16, TVal)>),
}

impl TVal {
    pub fn as_i64(&self) -> Option<i64> {
        match self { TVal::I64(v) => Some(*v), TVal::Byte(v) => Some(*v as i64), TVal::Bool(b) => Some(if *b {1} else {0}), _ => None }
    }
    pub fn as_bytes(&self) -> Option<&[u8]> {
        match self { TVal::Binary(b) => Some(b), _ => None }
    }
    pub fn as_list(&self) -> Option<&Vec<TVal>> {
        match self { TVal::List(l) => Some(l), _ => None }
    }
    pub fn as_struct(&self) -> Option<&Vec<(i16, TVal)>> {
        match self { TVal::Struct(s) => Some(s), _ => None }
    }
}

pub fn get<'a>(s: &'a [(i16, TVal)], fid: i16) -> Option<&'a TVal> {
    s.iter().find(|(id, _)| *id == fid).map(|(_, v)| v)
}
pub fn get_i64(s: &[(i16, TVal)], fid: i16) -> Option<i64> { get(s, fid).and_then(|v| v.as_i64()) }
pub fn get_bytes(s: &[(i16, TVal)], fid: i16) -> Option<Vec<u8>> { get(s, fid).and_then(|v| v.as_bytes().map(|b| b.to_vec())) }
pub fn get_bool(s: &[(i16, TVal)], fid: i16) -> Option<bool> {
    match get(s, fid) { Some(TVal::Bool(b)) => Some(*b), _ => None }
}

pub struct Reader<'a> {
    pub data: &'a [u8],
    pub pos: usize,
}

impl<'a> Reader<'a> {
    pub fn new(data: &'a [u8]) -> Self { Self { data, pos: 0 } }
    pub fn byte(&mut self) -> Result<u8, String> {
        if self.pos >= self.data.len() { return Err("EOF: unexpected end of thrift data".to_string()); }
        let b = self.data[self.pos]; self.pos += 1; Ok(b)
    }
    pub fn varint(&mut self) -> Result<u64, String> {
        let mut shift = 0u32; let mut result: u64 = 0;
        loop {
            let b = self.byte()?;
            result |= ((b & 0x7f) as u64) << shift;
            if b & 0x80 == 0 { break; }
            shift += 7;
            if shift > 63 { return Err("Parquet error: invalid varint".to_string()); }
        }
        Ok(result)
    }
    pub fn zigzag(&mut self) -> Result<i64, String> {
        let n = self.varint()?; Ok(((n >> 1) as i64) ^ -((n & 1) as i64))
    }
    pub fn read_value(&mut self, ctype: u8) -> Result<TVal, String> {
        match ctype {
            1 => Ok(TVal::Bool(true)),
            2 => Ok(TVal::Bool(false)),
            3 => Ok(TVal::Byte(self.byte()? as i8)),
            4 | 5 | 6 => Ok(TVal::I64(self.zigzag()?)),
            7 => {
                if self.pos + 8 > self.data.len() { return Err("EOF: unexpected end of thrift data".to_string()); }
                let mut buf = [0u8; 8]; buf.copy_from_slice(&self.data[self.pos..self.pos+8]); self.pos += 8;
                Ok(TVal::Double(f64::from_le_bytes(buf)))
            }
            8 => {
                let len = self.varint()? as usize;
                if self.pos + len > self.data.len() { return Err("EOF: unexpected end of thrift data".to_string()); }
                let v = self.data[self.pos..self.pos+len].to_vec(); self.pos += len; Ok(TVal::Binary(v))
            }
            9 | 10 => {
                let hb = self.byte()?; let size = (hb >> 4) as usize; let etype = hb & 0x0f;
                let size = if size == 15 { self.varint()? as usize } else { size };
                let mut out = Vec::with_capacity(size.min(100000));
                for _ in 0..size { out.push(self.read_elem(etype)?); }
                Ok(TVal::List(out))
            }
            11 => {
                let size = self.varint()? as usize;
                if size == 0 { return Ok(TVal::List(vec![])); }
                let hb = self.byte()?; let kt = hb >> 4; let vt = hb & 0x0f;
                let mut out = Vec::new();
                for _ in 0..size { let k = self.read_elem(kt)?; let v = self.read_elem(vt)?; out.push(k); out.push(v); }
                Ok(TVal::List(out))
            }
            12 => Ok(TVal::Struct(self.read_struct()?)),
            _ => Err(format!("Parquet error: invalid thrift compact type {}", ctype)),
        }
    }
    pub fn read_elem(&mut self, etype: u8) -> Result<TVal, String> {
        // For collection elements, boolean values are encoded as a single byte 1/2
        if etype == 1 || etype == 2 {
            // In element context, thrift compact encodes bool as byte; but struct field header already handled.
            // Elements of list<bool> use type id as value; treat following byte if needed - parquet doesn't have bool lists in metadata except sets of enums (ints)
            return self.read_value(etype);
        }
        self.read_value(etype)
    }
    pub fn read_struct(&mut self) -> Result<Vec<(i16, TVal)>, String> {
        let mut out = Vec::new();
        let mut last: i16 = 0;
        loop {
            let b = self.byte()?;
            if b == 0 { break; }
            let delta = b >> 4; let ctype = b & 0x0f;
            let fid = if delta == 0 { self.zigzag()? as i16 } else { last + delta as i16 };
            last = fid;
            let v = self.read_value(ctype)?;
            out.push((fid, v));
        }
        Ok(out)
    }
}

pub fn parse_struct(data: &[u8]) -> Result<(Vec<(i16, TVal)>, usize), String> {
    let mut r = Reader::new(data);
    let s = r.read_struct()?;
    Ok((s, r.pos))
}
RS
echo done"}

