{"command":"cat > src/metadata.rs <<'RS'
use crate::thrift::{get, get_bytes, get_i64, parse_struct, TVal};

#[derive(Debug, Clone, Default)]
pub struct Statistics {
    pub max_old: Option<Vec<u8>>,
    pub min_old: Option<Vec<u8>>,
    pub null_count: Option<i64>,
    pub distinct_count: Option<i64>,
    pub max_value: Option<Vec<u8>>,
    pub min_value: Option<Vec<u8>>,
}
impl Statistics {
    pub fn min_bytes(&self) -> Option<&[u8]> { self.min_value.as_deref().or(self.min_old.as_deref()) }
    pub fn max_bytes(&self) -> Option<&[u8]> { self.max_value.as_deref().or(self.max_old.as_deref()) }
}

#[derive(Debug, Clone)]
pub struct PageEncodingStats { pub page_type: i32, pub encoding: i32, pub count: i32 }

#[derive(Debug, Clone, Default)]
pub struct ColumnMeta {
    pub physical_type: i32,
    pub encodings: Vec<i32>,
    pub path: Vec<String>,
    pub codec: i32,
    pub num_values: i64,
    pub total_uncompressed: i64,
    pub total_compressed: i64,
    pub data_page_offset: i64,
    pub dict_page_offset: Option<i64>,
    pub index_page_offset: Option<i64>,
    pub statistics: Option<Statistics>,
    pub encoding_stats: Option<Vec<PageEncodingStats>>,
    pub bloom_filter_offset: Option<i64>,
    pub bloom_filter_length: Option<i64>,
}

#[derive(Debug, Clone, Default)]
pub struct ColumnChunk {
    pub file_offset: i64,
    pub meta: Option<ColumnMeta>,
}

#[derive(Debug, Clone, Default)]
pub struct RowGroupMeta {
    pub columns: Vec<ColumnChunk>,
    pub total_byte_size: i64,
    pub num_rows: i64,
    pub total_compressed_size: Option<i64>,
    pub file_offset: Option<i64>,
}

#[derive(Debug, Clone, Default)]
pub struct LogicalType {
    pub kind_id: i16, // union field id
    pub fields: Vec<(i16, TVal)>, // inner struct fields for that type
}

#[derive(Debug, Clone, Default)]
pub struct SchemaElement {
    pub physical_type: Option<i32>,
    pub type_length: Option<i32>,
    pub repetition: Option<i32>,
    pub name: String,
    pub num_children: usize,
    pub converted_type: Option<i32>,
    pub scale: Option<i32>,
    pub precision: Option<i32>,
    pub logical_type: Option<LogicalType>,
}

#[derive(Debug, Clone, Default)]
pub struct FileMeta {
    pub version: i32,
    pub schema: Vec<SchemaElement>,
    pub num_rows: i64,
    pub row_groups: Vec<RowGroupMeta>,
    pub created_by: Option<String>,
    pub key_value: Vec<(String, String)>,
}

fn str_from_bytes(b: &[u8]) -> String { String::from_utf8_lossy(b).into_owned() }

pub fn parse_statistics(s: &[(i16, TVal)]) -> Statistics {
    Statistics {
        max_old: get_bytes(s, 1),
        min_old: get_bytes(s, 2),
        null_count: get_i64(s, 3),
        distinct_count: get_i64(s, 4),
        max_value: get_bytes(s, 5),
        min_value: get_bytes(s, 6),
    }
}

pub fn parse_column_meta(s: &[(i16, TVal)]) -> ColumnMeta {
    let mut m = ColumnMeta::default();
    m.physical_type = get_i64(s, 1).unwrap_or(0) as i32;
    if let Some(TVal::List(l)) = get(s, 2) { m.encodings = l.iter().filter_map(|v| v.as_i64().map(|x| x as i32)).collect(); }
    if let Some(TVal::List(l)) = get(s, 3) { m.path = l.iter().filter_map(|v| v.as_bytes().map(str_from_bytes)).collect(); }
    m.codec = get_i64(s, 4).unwrap_or(0) as i32;
    m.num_values = get_i64(s, 5).unwrap_or(0);
    m.total_uncompressed = get_i64(s, 6).unwrap_or(0);
    m.total_compressed = get_i64(s, 7).unwrap_or(0);
    m.data_page_offset = get_i64(s, 9).unwrap_or(0);
    m.index_page_offset = get_i64(s, 10);
    m.dict_page_offset = get_i64(s, 11);
    if let Some(TVal::Struct(st)) = get(s, 12) { m.statistics = Some(parse_statistics(st)); }
    if let Some(TVal::List(l)) = get(s, 13) {
        let mut v = Vec::new();
        for item in l { if let TVal::Struct(st) = item { v.push(PageEncodingStats { page_type: get_i64(st, 1).unwrap_or(0) as i32, encoding: get_i64(st, 2).unwrap_or(0) as i32, count: get_i64(st, 3).unwrap_or(0) as i32 }); } }
        m.encoding_stats = Some(v);
    }
    m.bloom_filter_offset = get_i64(s, 14).or_else(|| get_i64(s, 17));
    m.bloom_filter_length = get_i64(s, 15).or_else(|| get_i64(s, 18));
    m
}

pub fn parse_file_meta(footer: &[u8]) -> Result<FileMeta, String> {
    let (root, _) = parse_struct(footer)?;
    let mut meta = FileMeta::default();
    meta.version = get_i64(&root, 1).unwrap_or(0) as i32;
    if let Some(TVal::List(l)) = get(&root, 2) {
        for item in l {
            if let TVal::Struct(e) = item {
                let mut el = SchemaElement::default();
                el.physical_type = get_i64(e, 1).map(|x| x as i32);
                el.type_length = get_i64(e, 2).map(|x| x as i32);
                el.repetition = get_i64(e, 3).map(|x| x as i32);
                el.name = get_bytes(e, 4).map(|b| str_from_bytes(&b)).unwrap_or_default();
                el.num_children = get_i64(e, 5).unwrap_or(0) as usize;
                el.converted_type = get_i64(e, 6).map(|x| x as i32);
                el.scale = get_i64(e, 7).map(|x| x as i32);
                el.precision = get_i64(e, 8).map(|x| x as i32);
                if let Some(TVal::Struct(lt)) = get(e, 10) {
                    if let Some((fid, inner)) = lt.first() {
                        let fields = match inner { TVal::Struct(f) => f.clone(), _ => vec![] };
                        el.logical_type = Some(LogicalType { kind_id: *fid, fields });
                    }
                }
                meta.schema.push(el);
            }
        }
    }
    meta.num_rows = get_i64(&root, 3).unwrap_or(0);
    if let Some(TVal::List(rgs)) = get(&root, 4) {
        for rgv in rgs {
            if let TVal::Struct(rg) = rgv {
                let mut r = RowGroupMeta::default();
                if let Some(TVal::List(cols)) = get(rg, 1) {
                    for colv in cols {
                        if let TVal::Struct(col) = colv {
                            let mut chunk = ColumnChunk::default();
                            chunk.file_offset = get_i64(col, 2).unwrap_or(0);
                            if let Some(TVal::Struct(m)) = get(col, 3) { chunk.meta = Some(parse_column_meta(m)); }
                            r.columns.push(chunk);
                        }
                    }
                }
                r.total_byte_size = get_i64(rg, 2).unwrap_or(0);
                r.num_rows = get_i64(rg, 3).unwrap_or(0);
                r.file_offset = get_i64(rg, 5);
                r.total_compressed_size = get_i64(rg, 6);
                meta.row_groups.push(r);
            }
        }
    }
    if let Some(TVal::List(kvs)) = get(&root, 5) {
        for item in kvs { if let TVal::Struct(kv) = item { meta.key_value.push((get_bytes(kv,1).map(|b| str_from_bytes(&b)).unwrap_or_default(), get_bytes(kv,2).map(|b| str_from_bytes(&b)).unwrap_or_default())); } }
    }
    meta.created_by = get_bytes(&root, 6).map(|b| str_from_bytes(&b));
    Ok(meta)
}

pub fn physical_name(t: i32) -> &'static str {
    match t { 0 => "BOOLEAN", 1 => "INT32", 2 => "INT64", 3 => "INT96", 4 => "FLOAT", 5 => "DOUBLE", 6 => "BYTE_ARRAY", 7 => "FIXED_LEN_BYTE_ARRAY", _ => "UNKNOWN" }
}
pub fn repetition_name(t: Option<i32>) -> &'static str {
    match t { Some(0) => "REQUIRED", Some(1) => "OPTIONAL", Some(2) => "REPEATED", _ => "" }
}
pub fn encoding_name(t: i32) -> &'static str {
    match t {
        0 => "PLAIN", 2 => "PLAIN_DICTIONARY", 3 => "RLE", 4 => "BIT_PACKED", 5 => "DELTA_BINARY_PACKED",
        6 => "DELTA_LENGTH_BYTE_ARRAY", 7 => "DELTA_BYTE_ARRAY", 8 => "RLE_DICTIONARY", 9 => "BYTE_STREAM_SPLIT",
        _ => "UNKNOWN",
    }
}
pub fn encoding_display(t: i32) -> &'static str {
    match t {
        0 => "Plain", 2 => "Plain Dictionary", 3 => "RLE", 4 => "Bit Packed", 5 => "Delta Binary Packed",
        6 => "Delta Length Byte Array", 7 => "Delta Byte Array", 8 => "RLE Dictionary", 9 => "Byte Stream Split",
        _ => "UNKNOWN",
    }
}
pub fn codec_name(t: i32) -> String {
    match t {
        0 => "UNCOMPRESSED".to_string(),
        1 => "SNAPPY".to_string(),
        2 => "GZIP(GzipLevel(6))".to_string(), // level refined later from page/file? Parquet codec stored only id; parquet-rs Compression display includes default level?
        3 => "LZO".to_string(),
        4 => "BROTLI(BrotliLevel(2))".to_string(), // placeholder, refined below
        5 => "LZ4".to_string(),
        6 => "ZSTD(ZstdLevel(1))".to_string(),
        7 => "LZ4_RAW".to_string(),
        _ => format!("UNKNOWN({})", t),
    }
}
RS
echo done"}

