    let mut m = ColumnMeta::default();
    m.physical_type = get_i64(s, 1).unwrap_or(0) as i32;
    if let Some(TVal::List(l)) = get(s, 2) { m.encodings = l.iter().filter_map(|v| v.as_i64().map(|x| x as i32)).collect(); }
    if let Some(TVal::List(l)) = get(s, 3) { m.path = l.iter().filter_map(|v| v.as_bytes().map(str_from_bytes)).collect(); }
