    if let Some(TVal::List(l)) = get(s, 13) {
        let mut v = Vec::new();
        for item in l { if let TVal::Struct(st) = item { v.push(PageEncodingStats { page_type: get_i64(st, 1).unwrap_or(0) as i32, encoding: get_i64(st, 2).unwrap_or(0) as i32, count: get_i64(st, 3).unwrap_or(0) as i32 }); } }
