                        el.logical_type = Some(LogicalType { kind_id: *fid, fields });
                    }
                }
                meta.schema.push(el);
            }
        }
    }
    meta.num_rows = get_i64(&root, 3).unwrap_or(0);
    if let Some(TVal::List(rgs)) = get(&root, 4) {
        for rgv in rgs {
            if let TVal::Struct(rg) = rgv {
                let mut r = RowGroupMeta::default();
                if let Some(TVal::List(cols)) = get(rg, 1) {
                    for colv in cols {
                        if let TVal::Struct(col) = colv {
                            let mut chunk = ColumnChunk::default();
                            chunk.file_offset = get_i64(col, 2).unwrap_or(0);
                            if let Some(TVal::Struct(m)) = get(col, 3) { chunk.meta = Some(parse_column_meta(m)); }
