{"command":"cat > src/model.rs <<'RS'
use crate::metadata::SchemaElement;
use chrono::{DateTime, NaiveDate, NaiveDateTime, NaiveTime};

#[derive(Debug, Clone, PartialEq)]
pub enum PrimVal {
    Bool(bool),
    I32(i32),
    I64(i64),
    Int96 { nanos: u64, julian_day: u32 },
    F32(f32),
    F64(f64),
    Bytes(Vec<u8>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TimeUnit { Second, Millis, Micros, Nanos }

impl TimeUnit {
    pub fn to_ns_factor(&self) -> i128 {
        match self { TimeUnit::Second => 1_000_000_000, TimeUnit::Millis => 1_000_000, TimeUnit::Micros => 1_000, TimeUnit::Nanos => 1 }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i128),
    UInt(u128),
    Float32(f32),
    Float64(f64),
    String(String),
    Binary(Vec<u8>),
    Date(i32),
    Datetime(i128, TimeUnit, Option<String>), // value in unit since epoch
    Time(i64), // ns since midnight
    Duration(i128, TimeUnit),
    Decimal(i128, i32),
    List(Vec<Value>),
    Struct(Vec<Value>),
}

pub fn format_float32(v: f32) -> String { format_float64(v as f64, true) }
pub fn format_float64(v: f64, _is32: bool) -> String {
    if v.is_nan() { return "NaN".to_string(); }
    if v.is_infinite() { return if v > 0.0 { "inf".to_string() } else { "-inf".to_string() }; }
    // Rust Display for floats in Polars AnyValue: uses ryu shortest; ensure a decimal point
    let mut s = format!("{}", v);
    if !s.contains('.') && !s.contains('e') && !s.contains("inf") && !s.contains("NaN") { s.push_str(".0"); }
    s
}

pub fn format_binary(bytes: &[u8]) -> String {
    let mut s = String::from("b\"");
    for b in bytes {
        if b.is_ascii_graphic() || *b == b' ' { s.push(*b as char); } else { s.push_str(&format!("\\x{:02x}", b)); }
    }
    s.push('"');
    s
}

pub fn format_decimal(mut v: i128, scale: i32) -> String {
    if scale <= 0 { return v.to_string(); }
    let scale = scale as usize;
    let neg = v < 0; if neg { v = -v; }
    let s = v.to_string();
    let padded = format!("{:0>width$}", s, width = scale + 1);
    let (int_part, frac) = padded.split_at(padded.len() - scale);
    format!("{}{}.{}", if neg { "-" } else { "" }, int_part, frac)
}

pub fn int96_to_ns(nanos: u64, julian_day: u32) -> i128 {
    // julian day -> unix days: unix epoch is Julian day 2440588
    let days = julian_day as i128 - 2440588;
    days * 86400 * 1_000_000_000i128 + nanos as i128
}

pub fn format_datetime_value(v: i128, unit: TimeUnit, tz: &Option<String>) -> String {
    // Convert to ns since epoch
    let ns = v * unit.to_ns_factor();
    // Without tz or UTC, format as naive UTC
    let secs = (ns.div_euclid(1_000_000_000)) as i64;
    let nsecs = (ns.rem_euclid(1_000_000_000)) as u32;
    let dt = DateTime::from_timestamp(secs, nsecs).map(|d| d.naive_utc());
    match dt {
        Some(ndt) => format_naive_datetime(ndt),
        None => format!("{}", ns),
    }
    // tz handling refined later if needed
    // Note: tz not used yet
}

pub fn format_naive_datetime(ndt: NaiveDateTime) -> String {
    // chrono Display prints fractional seconds only if nonzero, with trailing zeros trimmed in groups of 3
    format!("{}", ndt)
}

pub fn format_date(days: i32) -> String {
    match NaiveDate::from_num_days_from_ce_opt(days + 719163) {
        Some(d) => format!("{}", d),
        None => days.to_string(),
    }
}

pub fn format_time(ns: i64) -> String {
    let total_secs = ns.div_euclid(1_000_000_000);
    let nsec = ns.rem_euclid(1_000_000_000) as u32;
    let secs_day = total_secs.rem_euclid(86400) as u32;
    match NaiveTime::from_num_seconds_from_midnight_opt(secs_day, nsec) {
        Some(t) => format!("{}", t),
        None => ns.to_string(),
    }
}

/// Format a value the way Polars' AnyValue Display does (for nested contexts)
pub fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Int(i) => i.to_string(),
        Value::UInt(u) => u.to_string(),
        Value::Float32(f) => format_float32(*f),
        Value::Float64(f) => format_float64(*f, false),
        Value::String(s) => format!("\"{}\"", s),
        Value::Binary(b) => format_binary(b),
        Value::Date(d) => format_date(*d),
        Value::Datetime(v, u, tz) => format_datetime_value(*v, *u, tz),
        Value::Time(ns) => format_time(*ns),
        Value::Duration(v, u) => {
            // Polars Duration display: approximate chrono duration formatting
            let ns = v * u.to_ns_factor();
            format_duration_ns(ns)
        }
        Value::Decimal(v, s) => format_decimal(*v, *s),
        Value::List(items) => {
            let mut s = String::from("[");
            for (i, item) in items.iter().enumerate() { if i > 0 { s.push_str(", "); } s.push_str(&format_value(item)); }
            s.push(']');
            s
        }
        Value::Struct(fields) => {
            let mut s = String::from("{");
            for (i, item) in fields.iter().enumerate() { if i > 0 { s.push(','); } s.push_str(&format_value(item)); }
            s.push('}');
            s
        }
    }
