pub fn format_decimal(mut v: i128, scale: i32) -> String {
    if scale <= 0 { return v.to_string(); }
    let scale = scale as usize;
    let neg = v < 0; if neg { v = -v; }
    let s = v.to_string();
    let padded = format!("{:0>width$}", s, width = scale + 1);
    let (int_part, frac) = padded.split_at(padded.len() - scale);
    format!("{}{}.{}", if neg { "-" } else { "" }, int_part, frac)
