{"command":"cat > src/schema.rs <<'RS'
use crate::metadata::{LogicalType, SchemaElement};
use crate::model::{TimeUnit, Value, PrimVal};
use crate::thrift::{get_i64, TVal};

#[derive(Debug, Clone)]
pub struct Node {
    pub el: SchemaElement,
    pub children: Vec<usize>,
    pub parent: Option<usize>,
    pub leaf_index: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct SchemaTree {
    pub nodes: Vec<Node>,
    pub root: usize,
    pub leaves: Vec<usize>, // node indices in DFS order
}

pub fn build_tree(elements: &[SchemaElement]) -> Result<SchemaTree, String> {
    if elements.is_empty() { return Err("Parquet error: empty schema".to_string()); }
    // validate physical types like parquet-rs does
    for el in elements {
        if let Some(t) = el.physical_type {
            if !(0..=7).contains(&t) {
                return Err(format!("Parquet error: unexpected parquet type: {}", t));
            }
        }
    }
    let mut nodes: Vec<Node> = Vec::new();
    let mut pos = 0usize;
    let root = build_node(elements, &mut pos, None, &mut nodes)?;
    // assign leaves DFS
    let mut leaves = Vec::new();
    fn collect(nodes: &mut Vec<Node>, idx: usize, leaves: &mut Vec<usize>) {
        let is_leaf = nodes[idx].children.is_empty() && nodes[idx].el.physical_type.is_some();
        if is_leaf {
            let li = leaves.len();
            nodes[idx].leaf_index = Some(li);
            leaves.push(idx);
        } else {
            let children = nodes[idx].children.clone();
            for c in children { collect(nodes, c, leaves); }
        }
    }
    collect(&mut nodes, root, &mut leaves);
    Ok(SchemaTree { nodes, root, leaves })
}

fn build_node(elements: &[SchemaElement], pos: &mut usize, parent: Option<usize>, nodes: &mut Vec<Node>) -> Result<usize, String> {
    if *pos >= elements.len() { return Err("Parquet error: unexpected end of schema".to_string()); }
    let el = elements[*pos].clone(); *pos += 1;
    let idx = nodes.len();
    let nchild = el.num_children;
    nodes.push(Node { el, children: vec![], parent, leaf_index: None });
    let mut child_idxs = Vec::new();
    for _ in 0..nchild {
        let c = build_node(elements, pos, Some(idx), nodes)?;
        child_idxs.push(c);
    }
    nodes[idx].children = child_idxs;
    Ok(idx)
}

// Logical type helpers
pub fn logical_kind(el: &SchemaElement) -> Option<i16> { el.logical_type.as_ref().map(|l| l.kind_id) }
pub fn is_list(el: &SchemaElement) -> bool { logical_kind(el) == Some(3) || el.converted_type == Some(3) }
pub fn is_map(el: &SchemaElement) -> bool { logical_kind(el) == Some(2) || el.converted_type == Some(1) }

pub fn unit_from_logical(lt: &LogicalType) -> TimeUnit {
    // fields: 2 = unit struct; unit struct has one field: 1 MILLIS, 2 MICROS, 3 NANOS
    for (fid, v) in &lt.fields {
        if *fid == 2 {
            if let TVal::Struct(u) = v {
                if let Some((uid, _)) = u.first() {
                    return match uid { 1 => TimeUnit::Millis, 2 => TimeUnit::Micros, 3 => TimeUnit::Nanos, _ => TimeUnit::Millis };
                }
            }
        }
    }
    TimeUnit::Millis
}

#[derive(Debug, Clone, PartialEq)]
pub enum PrimKind {
    Bool,
    Int8, Int16, Int32, Int64,
    UInt8, UInt16, UInt32, UInt64,
    Float32, Float64,
    Binary,
    Str,
    Date,
    Datetime(TimeUnit, Option<String>),
    Time(TimeUnit),
    Decimal(i32, i32), // scale, precision
    NullType,
    Float16,
}

pub fn prim_kind(el: &SchemaElement) -> PrimKind {
    let phys = el.physical_type.unwrap_or(0);
    let lk = logical_kind(el);
    let conv = el.converted_type;
    // decimal check first for relevant physical types
    let is_decimal = lk == Some(5) || conv == Some(5);
    if is_decimal && matches!(phys, 1 | 2 | 6 | 7) {
        let (mut scale, mut prec) = (el.scale.unwrap_or(0), el.precision.unwrap_or(0));
        if let Some(lt) = &el.logical_type {
            if lt.kind_id == 5 {
                if let Some(s) = get_i64(&lt.fields, 1) { scale = s as i32; }
                if let Some(p) = get_i64(&lt.fields, 2) { prec = p as i32; }
            }
        }
        return PrimKind::Decimal(scale, prec);
    }
    match phys {
        0 => PrimKind::Bool,
        1 => {
            if lk == Some(6) || conv == Some(6) { return PrimKind::Date; }
            if lk == Some(7) || conv == Some(7) || conv == Some(8) {
                if let Some(lt) = &el.logical_type { return PrimKind::Time(unit_from_logical(lt)); }
                return PrimKind::Time(if conv == Some(8) { TimeUnit::Micros } else { TimeUnit::Millis });
            }
            if lk == Some(10) {
                if let Some(lt) = &el.logical_type {
                    let bw = get_i64(&lt.fields, 1).unwrap_or(32);
                    let signed = matches!(crate::thrift::get(&lt.fields, 2), Some(TVal::Bool(true)));
                    return match (bw, signed) { (8, true) => PrimKind::Int8, (8, false) => PrimKind::UInt8, (16, true) => PrimKind::Int16, (16, false) => PrimKind::UInt16, (32, false) => PrimKind::UInt32, (64, true) => PrimKind::Int64, (64, false) => PrimKind::UInt64, (_, true) => PrimKind::Int32, _ => PrimKind::UInt32 };
                }
            }
            match conv { Some(15) => PrimKind::Int8, Some(16) => PrimKind::Int16, Some(11) => PrimKind::UInt8, Some(12) => PrimKind::UInt16, Some(13) => PrimKind::UInt32, _ => PrimKind::Int32 }
        }
        2 => {
            if lk == Some(8) {
                if let Some(lt) = &el.logical_type {
                    let unit = unit_from_logical(lt);
                    let adjusted = matches!(crate::thrift::get(&lt.fields, 1), Some(TVal::Bool(true)));
                    let _ = adjusted;
                    return PrimKind::Datetime(unit, None);
                }
                return PrimKind::Datetime(TimeUnit::Millis, None);
            }
            if conv == Some(9) { return PrimKind::Datetime(TimeUnit::Millis, None); }
            if conv == Some(10) { return PrimKind::Datetime(TimeUnit::Micros, None); }
            if lk == Some(7) {
                if let Some(lt) = &el.logical_type { return PrimKind::Time(unit_from_logical(lt)); }
                return PrimKind::Time(TimeUnit::Micros);
            }
            if lk == Some(6) || conv == Some(6) { return PrimKind::Date; } // date64-ish; treat value as days? refined in convert
            if lk == Some(10) {
                if let Some(lt) = &el.logical_type {
                    let bw = get_i64(&lt.fields, 1).unwrap_or(64);
                    let signed = matches!(crate::thrift::get(&lt.fields, 2), Some(TVal::Bool(true)));
                    return match (bw, signed) { (64, false) => PrimKind::UInt64, (32, false) => PrimKind::UInt32, (32, true) => PrimKind::Int32, (16, true) => PrimKind::Int16, (16, false) => PrimKind::UInt16, (8, true) => PrimKind::Int8, (8, false) => PrimKind::UInt8, _ => PrimKind::Int64 };
                }
            }
            match conv { Some(14) => PrimKind::UInt64, Some(18) => PrimKind::Int64, _ => PrimKind::Int64 }
        }
        3 => PrimKind::Datetime(TimeUnit::Nanos, None),
        4 => PrimKind::Float32,
        5 => PrimKind::Float64,
        6 | 7 => {
            if lk == Some(11) { return PrimKind::NullType; }
            if lk == Some(15) || lk == Some(16) { /* float16 candidate for fixed 2 */ if phys == 7 && el.type_length == Some(2) { return PrimKind::Float16; } }
            if lk == Some(1) || lk == Some(4) || lk == Some(12) || conv == Some(0) || conv == Some(4) || conv == Some(19) { return PrimKind::Str; }
            PrimKind::Binary
        }
        _ => PrimKind::Binary,
    }
}

pub fn convert_prim(v: &PrimVal, kind: &PrimKind) -> Result<Value, String> {
    Ok(match (v, kind) {
        (_, PrimKind::NullType) => Value::Null,
        (PrimVal::Bool(b), _) => Value::Bool(*b),
        (PrimVal::I32(x), PrimKind::UInt8) => Value::UInt((*x as u8) as u128),
        (PrimVal::I32(x), PrimKind::UInt16) => Value::UInt((*x as u16) as u128),
        (PrimVal::I32(x), PrimKind::UInt32) => Value::UInt((*x as u32) as u128),
        (PrimVal::I32(x), PrimKind::Int8) => Value::Int((*x as i8) as i128),
        (PrimVal::I32(x), PrimKind::Int16) => Value::Int((*x as i16) as i128),
        (PrimVal::I32(x), _) if matches!(kind, PrimKind::Decimal(_, _)) => {
            if let PrimKind::Decimal(s, _) = kind { Value::Decimal(*x as i128, *s) } else { unreachable!() }
        }
        (PrimVal::I32(x), PrimKind::Date) => Value::Date(*x),
        (PrimVal::I32(x), PrimKind::Time(u)) => Value::Time((*x as i64) * (u.to_ns_factor() as i64 / 1) / 1 * 1), // careful below
        (PrimVal::I32(x), _) => Value::Int(*x as i128),
        (PrimVal::I64(x), PrimKind::UInt64) => Value::UInt((*x as u64) as u128),
        (PrimVal::I64(x), PrimKind::UInt32) => Value::UInt((*x as u32) as u128),
        (PrimVal::I64(x), _) if matches!(kind, PrimKind::Decimal(_, _)) => {
            if let PrimKind::Decimal(s, _) = kind { Value::Decimal(*x as i128, *s) } else { unreachable!() }
        }
        (PrimVal::I64(x), PrimKind::Datetime(u, tz)) => Value::Datetime(*x as i128, *u, tz.clone()),
        (PrimVal::I64(x), PrimKind::Time(u)) => Value::Time((*x as i128 * u.to_ns_factor()) as i64),
        (PrimVal::I64(x), PrimKind::Date) => Value::Date((*x / 86400000) as i32), // date64 ms fallback
        (PrimVal::I64(x), _) => Value::Int(*x as i128),
        (PrimVal::Int96 { nanos, julian_day }, _) => {
            let ns = crate::model::int96_to_ns(*nanos, *julian_day);
            Value::Datetime(ns, TimeUnit::Nanos, None)
        }
        (PrimVal::F32(x), _) => Value::Float32(*x),
        (PrimVal::F64(x), _) => Value::Float64(*x),
        (PrimVal::Bytes(b), PrimKind::Str) => Value::String(String::from_utf8_lossy(b).into_owned()),
        (PrimVal::Bytes(b), _) if matches!(kind, PrimKind::Decimal(_, _)) => {
            if let PrimKind::Decimal(s, _) = kind { Value::Decimal(bytes_to_i128(b), *s) } else { unreachable!() }
        }
        (PrimVal::Bytes(b), PrimKind::Float16) => Value::Float32(f16_to_f32(b)),
        (PrimVal::Bytes(b), _) => Value::Binary(b.clone()),
    })
}

pub fn bytes_to_i128(b: &[u8]) -> i128 {
    if b.is_empty() { return 0; }
    // big-endian two's complement, sign extend up to 16 bytes; for >16 bytes take low 16? (decimal256 case truncated)
    let mut bytes = b.to_vec();
    if bytes.len() > 16 { bytes = bytes[bytes.len()-16..].to_vec(); }
    let neg = bytes[0] & 0x80 != 0;
    let mut val: i128 = if neg { -1 } else { 0 };
    for byte in bytes { val = (val << 8) | (byte as i128); }
    val
}

pub fn f16_to_f32(b: &[u8]) -> f32 {
    if b.len() < 2 { return 0.0; }
    let h = u16::from_le_bytes([b[0], b[1]]);
    // use simple conversion
    let sign = ((h >> 15) & 1) as u32;
    let exp = ((h >> 10) & 0x1f) as i32;
    let frac = (h & 0x3ff) as u32;
    let bits: u32 = if exp == 0 {
        if frac == 0 { sign << 31 } else {
            // subnormal -> normalize
            let mut e = 127 - 15 + 1; let mut f = frac;
            while f & 0x400 == 0 { f <<= 1; e -= 1; }
            ((sign << 31) | ((e as u32) << 23) | ((f & 0x3ff) << 13))
        }
    } else if exp == 31 {
        (sign << 31) | (0xff << 23) | (frac << 13)
    } else {
        (sign << 31) | (((exp - 15 + 127) as u32) << 23) | (frac << 13)
    };
    f32::from_bits(bits)
}

// ---- Value schema (logical tree) ----
#[derive(Debug, Clone)]
pub enum VNode {
    Prim { leaf: usize, kind: PrimKind, max_def: i32 },
    Struct { fields: Vec<(String, VNode)>, present_def: i32 },
    List { elem: Box<VNode>, empty_def: i32, elem_def: i32, rep_level: i32 },
}

impl VNode {
    pub fn contains_leaf(&self, leaf: usize) -> bool {
        match self { VNode::Prim { leaf: l, .. } => *l == leaf, VNode::Struct { fields, .. } => fields.iter().any(|(_, f)| f.contains_leaf(leaf)), VNode::List { elem, .. } => elem.contains_leaf(leaf) }
    }
    pub fn leaves(&self) -> Vec<usize> {
        match self { VNode::Prim { leaf, .. } => vec![*leaf], VNode::Struct { fields, .. } => fields.iter().flat_map(|(_, f)| f.leaves()).collect(), VNode::List { elem, .. } => elem.leaves() }
    }
}

fn def_inc(rep: Option<i32>) -> i32 { match rep { Some(1) | Some(2) => 1, _ => 0 } }
fn rep_inc(rep: Option<i32>) -> i32 { if rep == Some(2) { 1 } else { 0 } }

pub struct VBuilder<'a> { pub tree: &'a SchemaTree }

impl<'a> VBuilder<'a> {
    pub fn build_root_columns(&self) -> Vec<(String, VNode)> {
        let root = &self.tree.nodes[self.tree.root];
        root.children.iter().map(|&c| {
            let name = self.tree.nodes[c].el.name.clone();
            (name, self.build(c, 0, 0))
        }).collect()
    }

    fn build_struct_fields(&self, children: &[usize], cum_def: i32, cum_rep: i32) -> Vec<(String, VNode)> {
        children.iter().map(|&c| (self.tree.nodes[c].el.name.clone(), self.build(c, cum_def, cum_rep))).collect()
    }

    pub fn build(&self, idx: usize, cum_def_before: i32, cum_rep_before: i32) -> VNode {
        let node = &self.tree.nodes[idx];
        let el = &node.el;
        let cum_def = cum_def_before + def_inc(el.repetition);
        let cum_rep = cum_rep_before + rep_inc(el.repetition);

        // Primitive
        if node.children.is_empty() && el.physical_type.is_some() {
            let leaf = node.leaf_index.unwrap_or(0);
            let kind = prim_kind(el);
            if el.repetition == Some(2) {
                // repeated primitive -> list
                return VNode::List { elem: Box::new(VNode::Prim { leaf, kind, max_def: cum_def }), empty_def: cum_def_before, elem_def: cum_def, rep_level: cum_rep };
            }
            return VNode::Prim { leaf, kind, max_def: cum_def };
        }

        // Group
        if is_list(el) {
            // single repeated child
            if node.children.len() == 1 {
                let child_idx = node.children[0];
                let child = &self.tree.nodes[child_idx];
                let elem_def = cum_def + 1;
                let rep_level = cum_rep + 1;
                let elem: VNode = if child.children.is_empty() && child.el.physical_type.is_some() {
                    // repeated primitive is the element
                    VNode::Prim { leaf: child.leaf_index.unwrap_or(0), kind: prim_kind(&child.el), max_def: elem_def }
                } else if child.children.len() == 1 && (child.el.name == "list" || child.el.name == "array") {
                    let g = child.children[0];
                    self.build_with_cum(g, elem_def, rep_level)
                } else if child.children.len() == 1 {
                    // Determine if single child is element (standard list uses repeated named list, handled above)
                    // Legacy: repeated group with single field named e.g. "item"? if grandchild name is ??? treat repeated group as struct if it looks like a struct element:
                    // If the single grandchild is itself a group, treat repeated as element struct; otherwise element is grandchild.
                    let g = child.children[0];
                    let gnode = &self.tree.nodes[g];
                    if gnode.children.is_empty() {
                        // element is the grandchild primitive (e.g., repeated group "list" not named list but still standard)
                        // But to be safe: if repeated group's name is not a known container, element could be 1-field struct.
                        // parquet spec: if repeated group has one primitive child and is not named list/array, it's ambiguous.
                        // Arrow tends to treat the repeated group as the element when name != "list".
                        // However most modern files name it "list". Check repeated name:
                        if child.el.name == "list" || child.el.name == "array" || child.el.name.ends_with("_tuple") {
                            self.build_with_cum(g, elem_def, rep_level)
                        } else {
                            // treat repeated group as struct element with one field
                            let fields = self.build_struct_fields(&child.children, elem_def, rep_level);
                            VNode::Struct { fields, present_def: elem_def }
                        }
                    } else {
                        self.build_with_cum(g, elem_def, rep_level)
                    }
                } else {
                    // repeated group is element struct
                    let fields = self.build_struct_fields(&child.children, elem_def, rep_level);
                    VNode::Struct { fields, present_def: elem_def }
                };
                return VNode::List { elem: Box::new(elem), empty_def: cum_def, elem_def, rep_level };
            }
        }

        if is_map(el) {
            if node.children.len() == 1 {
                let child_idx = node.children[0];
                let child = &self.tree.nodes[child_idx];
                let elem_def = cum_def + 1;
                let rep_level = cum_rep + 1;
                let fields = self.build_struct_fields(&child.children, elem_def, rep_level);
                let elem = VNode::Struct { fields, present_def: elem_def };
                return VNode::List { elem: Box::new(elem), empty_def: cum_def, elem_def, rep_level };
            }
        }

        // Repeated group (not list/map parent) -> list of struct / etc
        if el.repetition == Some(2) {
            let elem_def = cum_def; // includes repeated inc
            let fields = self.build_struct_fields(&node.children, cum_def, cum_rep);
            let elem = VNode::Struct { fields, present_def: elem_def };
            return VNode::List { elem: Box::new(elem), empty_def: cum_def_before, elem_def, rep_level: cum_rep };
        }

        // Plain struct
        let fields = self.build_struct_fields(&node.children, cum_def, cum_rep);
        VNode::Struct { fields, present_def: cum_def }
    }

    // Build a node where its cumulative def/rep before it are given, computing normally (used for list elements)
    fn build_with_cum(&self, idx: usize, cum_def_before: i32, cum_rep_before: i32) -> VNode {
        self.build(idx, cum_def_before, cum_rep_before)
    }
}
RS
