use crate::metadata::{LogicalType, SchemaElement};
use crate::model::{TimeUnit, Value, PrimVal};
use crate::thrift::{get_i64, TVal};

#[derive(Debug, Clone)]
pub struct Node {
    pub el: SchemaElement,
    pub children: Vec<usize>,
    pub parent: Option<usize>,
    pub leaf_index: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct SchemaTree {
    pub nodes: Vec<Node>,
    pub root: usize,
    pub leaves: Vec<usize>, // node indices in DFS order
}

pub fn build_tree(elements: &[SchemaElement]) -> Result<SchemaTree, String> {
    if elements.is_empty() { return Err("Parquet error: empty schema".to_string()); }
    // validate physical types like parquet-rs does
    for el in elements {
        if let Some(t) = el.physical_type {
            if !(0..=7).contains(&t) {
                return Err(format!("Parquet error: unexpected parquet type: {}", t));
            }
        }
    }
    let mut nodes: Vec<Node> = Vec::new();
    let mut pos = 0usize;
    let root = build_node(elements, &mut pos, None, &mut nodes)?;
    // assign leaves DFS
    let mut leaves = Vec::new();
    fn collect(nodes: &mut Vec<Node>, idx: usize, leaves: &mut Vec<usize>) {
        let is_leaf = nodes[idx].children.is_empty() && nodes[idx].el.physical_type.is_some();
        if is_leaf {
            let li = leaves.len();
            nodes[idx].leaf_index = Some(li);
            leaves.push(idx);
        } else {
            let children = nodes[idx].children.clone();
            for c in children { collect(nodes, c, leaves); }
        }
    }
    collect(&mut nodes, root, &mut leaves);
    Ok(SchemaTree { nodes, root, leaves })
}

fn build_node(elements: &[SchemaElement], pos: &mut usize, parent: Option<usize>, nodes: &mut Vec<Node>) -> Result<usize, String> {
    if *pos >= elements.len() { return Err("Parquet error: unexpected end of schema".to_string()); }
    let el = elements[*pos].clone(); *pos += 1;
    let idx = nodes.len();
    let nchild = el.num_children;
    nodes.push(Node { el, children: vec![], parent, leaf_index: None });
    let mut child_idxs = Vec::new();
    for _ in 0..nchild {
        let c = build_node(elements, pos, Some(idx), nodes)?;
        child_idxs.push(c);
    }
    nodes[idx].children = child_idxs;
    Ok(idx)
}

// Logical type helpers
pub fn logical_kind(el: &SchemaElement) -> Option<i16> { el.logical_type.as_ref().map(|l| l.kind_id) }
pub fn is_list(el: &SchemaElement) -> bool { logical_kind(el) == Some(3) || el.converted_type == Some(3) }
pub fn is_map(el: &SchemaElement) -> bool { logical_kind(el) == Some(2) || el.converted_type == Some(1) }

pub fn unit_from_logical(lt: &LogicalType) -> TimeUnit {
    // fields: 2 = unit struct; unit struct has one field: 1 MILLIS, 2 MICROS, 3 NANOS
    for (fid, v) in &lt.fields {
        if *fid == 2 {
            if let TVal::Struct(u) = v {
                if let Some((uid, _)) = u.first() {
                    return match uid { 1 => TimeUnit::Millis, 2 => TimeUnit::Micros, 3 => TimeUnit::Nanos, _ => TimeUnit::Millis };
                }
            }
        }
    }
    TimeUnit::Millis
}

#[derive(Debug, Clone, PartialEq)]
pub enum PrimKind {
    Bool,
    Int8, Int16, Int32, Int64,
    UInt8, UInt16, UInt32, UInt64,
    Float32, Float64,
    Binary,
    Str,
    Date,
    Datetime(TimeUnit, Option<String>),
    Time(TimeUnit),
    Decimal(i32, i32), // scale, precision
    NullType,
    Float16,
}

pub fn prim_kind(el: &SchemaElement) -> PrimKind {
    let phys = el.physical_type.unwrap_or(0);
    let lk = logical_kind(el);
    let conv = el.converted_type;
    // decimal check first for relevant physical types
    let is_decimal = lk == Some(5) || conv == Some(5);
    if is_decimal && matches!(phys, 1 | 2 | 6 | 7) {
        let (mut scale, mut prec) = (el.scale.unwrap_or(0), el.precision.unwrap_or(0));
        if let Some(lt) = &el.logical_type {
            if lt.kind_id == 5 {
                if let Some(s) = get_i64(&lt.fields, 1) { scale = s as i32; }
                if let Some(p) = get_i64(&lt.fields, 2) { prec = p as i32; }
            }
        }
        return PrimKind::Decimal(scale, prec);
    }
    match phys {
        0 => PrimKind::Bool,
        1 => {
            if lk == Some(6) || conv == Some(6) { return PrimKind::Date; }
            if lk == Some(7) || conv == Some(7) || conv == Some(8) {
                if let Some(lt) = &el.logical_type { return PrimKind::Time(unit_from_logical(lt)); }
                return PrimKind::Time(if conv == Some(8) { TimeUnit::Micros } else { TimeUnit::Millis });
            }
            if lk == Some(10) {
                if let Some(lt) = &el.logical_type {
                    let bw = get_i64(&lt.fields, 1).unwrap_or(32);
                    let signed = matches!(crate::thrift::get(&lt.fields, 2), Some(TVal::Bool(true)));
                    return match (bw, signed) { (8, true) => PrimKind::Int8, (8, false) => PrimKind::UInt8, (16, true) => PrimKind::Int16, (16, false) => PrimKind::UInt16, (32, false) => PrimKind::UInt32, (64, true) => PrimKind::Int64, (64, false) => PrimKind::UInt64, (_, true) => PrimKind::Int32, _ => PrimKind::UInt32 };
                }
            }
            match conv { Some(15) => PrimKind::Int8, Some(16) => PrimKind::Int16, Some(11) => PrimKind::UInt8, Some(12) => PrimKind::UInt16, Some(13) => PrimKind::UInt32, _ => PrimKind::Int32 }
        }
        2 => {
            if lk == Some(8) {
                if let Some(lt) = &el.logical_type {
                    let unit = unit_from_logical(lt);
                    let adjusted = matches!(crate::thrift::get(&lt.fields, 1), Some(TVal::Bool(true)));
                    let _ = adjusted;
                    return PrimKind::Datetime(unit, None);
                }
                return PrimKind::Datetime(TimeUnit::Millis, None);
            }
            if conv == Some(9) { return PrimKind::Datetime(TimeUnit::Millis, None); }
            if conv == Some(10) { return PrimKind::Datetime(TimeUnit::Micros, None); }
            if lk == Some(7) {
                if let Some(lt) = &el.logical_type { return PrimKind::Time(unit_from_logical(lt)); }
                return PrimKind::Time(TimeUnit::Micros);
            }
            if lk == Some(6) || conv == Some(6) { return PrimKind::Date; } // date64-ish; treat value as days? refined in convert
            if lk == Some(10) {
                if let Some(lt) = &el.logical_type {
                    let bw = get_i64(&lt.fields, 1).unwrap_or(64);
                    let signed = matches!(crate::thrift::get(&lt.fields, 2), Some(TVal::Bool(true)));
                    return match (bw, signed) { (64, false) => PrimKind::UInt64, (32, false) => PrimKind::UInt32, (32, true) => PrimKind::Int32, (16, true) => PrimKind::Int16, (16, false) => PrimKind::UInt16, (8, true) => PrimKind::Int8, (8, false) => PrimKind::UInt8, _ => PrimKind::Int64 };
                }
            }
            match conv { Some(14) => PrimKind::UInt64, Some(18) => PrimKind::Int64, _ => PrimKind::Int64 }
        }
        3 => PrimKind::Datetime(TimeUnit::Nanos, None),
        4 => PrimKind::Float32,
        5 => PrimKind::Float64,
        6 | 7 => {
            if lk == Some(11) { return PrimKind::NullType; }
