// ---- Value schema (logical tree) ----
#[derive(Debug, Clone)]
pub enum VNode {
    Prim { leaf: usize, kind: PrimKind, max_def: i32 },
    Struct { fields: Vec<(String, VNode)>, present_def: i32 },
    List { elem: Box<VNode>, empty_def: i32, elem_def: i32, rep_level: i32 },
}

impl VNode {
    pub fn contains_leaf(&self, leaf: usize) -> bool {
        match self { VNode::Prim { leaf: l, .. } => *l == leaf, VNode::Struct { fields, .. } => fields.iter().any(|(_, f)| f.contains_leaf(leaf)), VNode::List { elem, .. } => elem.contains_leaf(leaf) }
    }
    pub fn leaves(&self) -> Vec<usize> {
        match self { VNode::Prim { leaf, .. } => vec![*leaf], VNode::Struct { fields, .. } => fields.iter().flat_map(|(_, f)| f.leaves()).collect(), VNode::List { elem, .. } => elem.leaves() }
    }
}

fn def_inc(rep: Option<i32>) -> i32 { match rep { Some(1) | Some(2) => 1, _ => 0 } }
fn rep_inc(rep: Option<i32>) -> i32 { if rep == Some(2) { 1 } else { 0 } }

pub struct VBuilder<'a> { pub tree: &'a SchemaTree }

impl<'a> VBuilder<'a> {
    pub fn build_root_columns(&self) -> Vec<(String, VNode)> {
        let root = &self.tree.nodes[self.tree.root];
        root.children.iter().map(|&c| {
            let name = self.tree.nodes[c].el.name.clone();
            (name, self.build(c, 0, 0))
        }).collect()
    }

    fn build_struct_fields(&self, children: &[usize], cum_def: i32, cum_rep: i32) -> Vec<(String, VNode)> {
        children.iter().map(|&c| (self.tree.nodes[c].el.name.clone(), self.build(c, cum_def, cum_rep))).collect()
    }

    pub fn build(&self, idx: usize, cum_def_before: i32, cum_rep_before: i32) -> VNode {
        let node = &self.tree.nodes[idx];
        let el = &node.el;
        let cum_def = cum_def_before + def_inc(el.repetition);
        let cum_rep = cum_rep_before + rep_inc(el.repetition);

        // Primitive
        if node.children.is_empty() && el.physical_type.is_some() {
            let leaf = node.leaf_index.unwrap_or(0);
            let kind = prim_kind(el);
            if el.repetition == Some(2) {
                // repeated primitive -> list
                return VNode::List { elem: Box::new(VNode::Prim { leaf, kind, max_def: cum_def }), empty_def: cum_def_before, elem_def: cum_def, rep_level: cum_rep };
            }
            return VNode::Prim { leaf, kind, max_def: cum_def };
        }

        // Group
        if is_list(el) {
            // single repeated child
            if node.children.len() == 1 {
                let child_idx = node.children[0];
                let child = &self.tree.nodes[child_idx];
                let elem_def = cum_def + 1;
                let rep_level = cum_rep + 1;
                let elem: VNode = if child.children.is_empty() && child.el.physical_type.is_some() {
                    // repeated primitive is the element
                    VNode::Prim { leaf: child.leaf_index.unwrap_or(0), kind: prim_kind(&child.el), max_def: elem_def }
                } else if child.children.len() == 1 && (child.el.name == "list" || child.el.name == "array") {
                    let g = child.children[0];
                    self.build_with_cum(g, elem_def, rep_level)
                } else if child.children.len() == 1 {
                    // Determine if single child is element (standard list uses repeated named list, handled above)
                    // Legacy: repeated group with single field named e.g. "item"? if grandchild name is ??? treat repeated group as struct if it looks like a struct element:
                    // If the single grandchild is itself a group, treat repeated as element struct; otherwise element is grandchild.
                    let g = child.children[0];
                    let gnode = &self.tree.nodes[g];
                    if gnode.children.is_empty() {
                        // element is the grandchild primitive (e.g., repeated group "list" not named list but still standard)
                        // But to be safe: if repeated group's name is not a known container, element could be 1-field struct.
                        // parquet spec: if repeated group has one primitive child and is not named list/array, it's ambiguous.
                        // Arrow tends to treat the repeated group as the element when name != "list".
                        // However most modern files name it "list". Check repeated name:
                        if child.el.name == "list" || child.el.name == "array" || child.el.name.ends_with("_tuple") {
                            self.build_with_cum(g, elem_def, rep_level)
                        } else {
