                            let fields = self.build_struct_fields(&child.children, elem_def, rep_level);
                            VNode::Struct { fields, present_def: elem_def }
                        }
                    } else {
                        self.build_with_cum(g, elem_def, rep_level)
                    }
                } else {
                    // repeated group is element struct
                    let fields = self.build_struct_fields(&child.children, elem_def, rep_level);
                    VNode::Struct { fields, present_def: elem_def }
                };
                return VNode::List { elem: Box::new(elem), empty_def: cum_def, elem_def, rep_level };
            }
        }

        if is_map(el) {
            if node.children.len() == 1 {
                let child_idx = node.children[0];
                let child = &self.tree.nodes[child_idx];
                let elem_def = cum_def + 1;
                let rep_level = cum_rep + 1;
                let fields = self.build_struct_fields(&child.children, elem_def, rep_level);
                let elem = VNode::Struct { fields, present_def: elem_def };
                return VNode::List { elem: Box::new(elem), empty_def: cum_def, elem_def, rep_level };
            }
        }

        // Repeated group (not list/map parent) -> list of struct / etc
        if el.repetition == Some(2) {
            let elem_def = cum_def; // includes repeated inc
            let fields = self.build_struct_fields(&node.children, cum_def, cum_rep);
            let elem = VNode::Struct { fields, present_def: elem_def };
            return VNode::List { elem: Box::new(elem), empty_def: cum_def_before, elem_def, rep_level: cum_rep };
        }

        // Plain struct
        let fields = self.build_struct_fields(&node.children, cum_def, cum_rep);
        VNode::Struct { fields, present_def: cum_def }
    }

    // Build a node where its cumulative def/rep before it are given, computing normally (used for list elements)
    fn build_with_cum(&self, idx: usize, cum_def_before: i32, cum_rep_before: i32) -> VNode {
        self.build(idx, cum_def_before, cum_rep_before)
    }
}
