pub fn convert_prim(v: &PrimVal, kind: &PrimKind) -> Result<Value, String> {
    Ok(match (v, kind) {
        (_, PrimKind::NullType) => Value::Null,
        (PrimVal::Bool(b), _) => Value::Bool(*b),
        (PrimVal::I32(x), PrimKind::UInt8) => Value::UInt((*x as u8) as u128),
        (PrimVal::I32(x), PrimKind::UInt16) => Value::UInt((*x as u16) as u128),
        (PrimVal::I32(x), PrimKind::UInt32) => Value::UInt((*x as u32) as u128),
        (PrimVal::I32(x), PrimKind::Int8) => Value::Int((*x as i8) as i128),
        (PrimVal::I32(x), PrimKind::Int16) => Value::Int((*x as i16) as i128),
        (PrimVal::I32(x), _) if matches!(kind, PrimKind::Decimal(_, _)) => {
            if let PrimKind::Decimal(s, _) = kind { Value::Decimal(*x as i128, *s) } else { unreachable!() }
        }
        (PrimVal::I32(x), PrimKind::Date) => Value::Date(*x),
        (PrimVal::I32(x), PrimKind::Time(u)) => Value::Time((*x as i64) * (u.to_ns_factor() as i64 / 1) / 1 * 1), // careful below
        (PrimVal::I32(x), _) => Value::Int(*x as i128),
