        (PrimVal::I64(x), PrimKind::UInt32) => Value::UInt((*x as u32) as u128),
        (PrimVal::I64(x), _) if matches!(kind, PrimKind::Decimal(_, _)) => {
            if let PrimKind::Decimal(s, _) = kind { Value::Decimal(*x as i128, *s) } else { unreachable!() }
        }
        (PrimVal::I64(x), PrimKind::Datetime(u, tz)) => Value::Datetime(*x as i128, *u, tz.clone()),
