pub fn bytes_to_i128(b: &[u8]) -> i128 {
    if b.is_empty() { return 0; }
    // big-endian two's complement, sign extend up to 16 bytes; for >16 bytes take low 16? (decimal256 case truncated)
    let mut bytes = b.to_vec();
    if bytes.len() > 16 { bytes = bytes[bytes.len()-16..].to_vec(); }
    let neg = bytes[0] & 0x80 != 0;
    let mut val: i128 = if neg { -1 } else { 0 };
    for byte in bytes { val = (val << 8) | (byte as i128); }
    val
}

pub fn f16_to_f32(b: &[u8]) -> f32 {
    if b.len() < 2 { return 0.0; }
    let h = u16::from_le_bytes([b[0], b[1]]);
