fn snappy_decompress(data: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    // Raw snappy block format
    let mut pos = 0usize;
    // varint uncompressed length
    let mut shift = 0u32; let mut len: usize = 0;
    loop {
        if pos >= data.len() { return Err("Parquet error: snappy decompress error".to_string()); }
        let b = data[pos]; pos += 1; len |= ((b & 0x7f) as usize) << shift;
        if b & 0x80 == 0 { break; }
        shift += 7;
    }
    if len != expected {
        // trust varint
    }
    let mut out: Vec<u8> = Vec::with_capacity(len);
    while pos < data.len() {
        let tag = data[pos]; pos += 1;
        match tag & 0x03 {
            0 => {
                let mut lit_len = (tag >> 2) as usize;
                if lit_len >= 60 {
                    let extra = lit_len - 59;
                    if pos + extra > data.len() { return Err("snappy error".to_string()); }
                    let mut v: usize = 0; for i in 0..extra { v |= (data[pos+i] as usize) << (8*i); }
                    pos += extra; lit_len = v;
                }
                lit_len += 1;
                if pos + lit_len > data.len() { return Err("snappy error".to_string()); }
                out.extend_from_slice(&data[pos..pos+lit_len]); pos += lit_len;
            }
            1 => {
                if pos >= data.len() { return Err("snappy error".to_string()); }
                let length = 4 + ((tag >> 2) & 0x7) as usize;
                let offset = (((tag >> 5) as usize) << 8) | data[pos] as usize; pos += 1;
                if offset == 0 || offset > out.len() { return Err("snappy offset error".to_string()); }
                for _ in 0..length { let b = out[out.len()-offset]; out.push(b); }
            }
            2 => {
                if pos + 2 > data.len() { return Err("snappy error".to_string()); }
                let length = 1 + (tag >> 2) as usize;
                let offset = u16::from_le_bytes([data[pos], data[pos+1]]) as usize; pos += 2;
                if offset == 0 || offset > out.len() { return Err("snappy offset error".to_string()); }
                for _ in 0..length { let b = out[out.len()-offset]; out.push(b); }
            }
            _ => {
                if pos + 4 > data.len() { return Err("snappy error".to_string()); }
                let length = 1 + (tag >> 2) as usize;
                let offset = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize; pos += 4;
                if offset == 0 || offset > out.len() { return Err("snappy offset error".to_string()); }
                for _ in 0..length { let b = out[out.len()-offset]; out.push(b); }
            }
        }
    }
    if out.len() != len { /* accept if close */ }
    Ok(out)
}

pub fn lz4_block_decompress(data: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let mut out: Vec<u8> = Vec::with_capacity(expected);
    let mut pos = 0usize;
    while pos < data.len() {
        let token = data[pos]; pos += 1;
        let mut lit_len = (token >> 4) as usize;
        if lit_len == 15 { loop { if pos>=data.len(){return Err("lz4 error".into());} let b=data[pos]; pos+=1; lit_len+=b as usize; if b!=255{break;} } }
        if pos+lit_len > data.len() { return Err("lz4 literals error".into()); }
        out.extend_from_slice(&data[pos..pos+lit_len]); pos+=lit_len;
        if pos >= data.len() { break; }
        if pos+2 > data.len() { return Err("lz4 offset error".into()); }
        let offset = u16::from_le_bytes([data[pos], data[pos+1]]) as usize; pos+=2;
        if offset==0 || offset>out.len() { return Err("lz4 offset invalid".into()); }
        let mut match_len = (token & 0x0f) as usize;
        if match_len==15 { loop { if pos>=data.len(){return Err("lz4 error".into());} let b=data[pos]; pos+=1; match_len+=b as usize; if b!=255{break;} } }
        match_len += 4;
        for _ in 0..match_len { let b=out[out.len()-offset]; out.push(b); }
    }
    Ok(out)
}

