}

pub fn iter_pages(file: &[u8], meta: &ColumnMeta) -> Result<Vec<PageInfo>, String> {
    let mut pages = Vec::new();
    let mut offset = meta.dict_page_offset.unwrap_or(meta.data_page_offset) as usize;
    let total = meta.total_compressed;
    if total < 0 { return Err("parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted".to_string()); }
    let end_limit = offset.checked_add(total as usize).ok_or("overflow")?;
    let mut consumed: usize = 0;
    while (consumed as i64) < total {
        if offset >= file.len() { return Err("EOF: Parquet file too small".to_string()); }
        let (info, hlen, _, _) = parse_page_header(file, offset)?;
        let page_total = hlen.checked_add(info.compressed_size as usize).ok_or("overflow")?;
        if offset + page_total > end_limit || offset + page_total > file.len() {
            return Err("parquet: File out of specification: The page header reported the wrong page size".to_string());
        }
        consumed += page_total;
        offset += page_total;
        pages.push(info);
    }
    Ok(pages)
}

fn bits_needed(max: i32) -> u32 {
    if max <= 0 { 0 } else { 32 - ((max as u32).leading_zeros()) }
    // actually bits needed to represent max: e.g., max=1 ->1, max=3->2
}

pub struct RleDecoder<'a> { data: &'a [u8], pos: usize, bit_pos: usize }
impl<'a> RleDecoder<'a> {
    pub fn new(data: &'a [u8]) -> Self { Self { data, pos: 0, bit_pos: 0 } }
    fn read_varint(&mut self) -> Result<u64, String> {
        let mut shift=0; let mut result=0u64;
        loop { if self.pos>=self.data.len(){return Err("EOF rle".into());} let b=self.data[self.pos]; self.pos+=1; result|=((b&0x7f) as u64)<<shift; if b&0x80==0{break;} shift+=7; }
        Ok(result)
    }
    fn read_bit(&mut self) -> u32 {
        if self.pos>=self.data.len(){return 0;}
        let byte=self.data[self.pos]; let bit=((byte>>self.bit_pos)&1) as u32; self.bit_pos+=1; if self.bit_pos==8{self.bit_pos=0; self.pos+=1;} bit
    }
    fn read_bits(&mut self, bw: u32) -> u64 { let mut v=0u64; for i in 0..bw { v |= (self.read_bit() as u64) << i; } v }
}

pub fn decode_rle_bp(data: &[u8], bit_width: u32, count: usize) -> Result<Vec<i64>, String> {
    let mut dec = RleDecoder::new(data);
    let mut out = Vec::with_capacity(count);
    while out.len() < count {
        let header = dec.read_varint()?;
        if header & 1 == 0 {
            let run = (header >> 1) as usize;
            let byte_len = ((bit_width + 7) / 8) as usize;
            let mut v: u64 = 0;
            if dec.bit_pos!=0 { dec.pos+=1; dec.bit_pos=0; }
            for i in 0..byte_len { if dec.pos>=data.len(){return Err("EOF rle run".into());} v |= (data[dec.pos] as u64) << (8*i); dec.pos+=1; }
            for _ in 0..run { if out.len()>=count{break;} out.push(v as i64); }
        } else {
            let groups = (header >> 1) as usize;
            let total = groups * 8;
            for _ in 0..total { if out.len()>=count{ /* still need consume bits */ } let v=dec.read_bits(bit_width); if out.len()<count { out.push(v as i64); } }
            // align to byte boundary (read_bits already ends on byte if total* bw multiple of 8? groups*8*bw is divisible by 8 if bw integer, yes if bw>0)
            if dec.bit_pos!=0 { dec.pos+=1; dec.bit_pos=0; }
        }
    }
    Ok(out)
}

pub fn decode_bit_packed_msb(data: &[u8], bit_width: u32, count: usize) -> Vec<i64> {
    let mut out=Vec::with_capacity(count);
    if bit_width==0 { return vec![0; count]; }
    let mut bit_pos=0usize;
    for _ in 0..count {
        let mut v: u64=0;
        for _ in 0..bit_width {
            let byte_idx=bit_pos/8; let bit_in_byte=7-(bit_pos%8);
            let bit = if byte_idx<data.len() { (data[byte_idx]>>bit_in_byte)&1 } else {0};
            v=(v<<1)|(bit as u64); bit_pos+=1;
        }
        out.push(v as i64);
    }
    out
}

pub fn decode_levels(data: &[u8], max_level: i32, count: usize, encoding: i32, is_v2: bool, offset: &mut usize) -> Result<Vec<i32>, String> {
    if max_level==0 { return Ok(vec![0; count]); }
    let bw=bits_needed(max_level);
    if is_v2 {
        // data slice already is exactly the levels bytes; caller passes sub-slice and offset ignored
        let vals=decode_rle_bp(data, bw, count)?;
        return Ok(vals.iter().map(|v|*v as i32).collect());
    }
    if encoding==3 { // RLE
        if *offset+4>data.len(){return Err("EOF levels".into());}
        let len=u32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]) as usize; *offset+=4;
        if *offset+len>data.len(){return Err("EOF levels data".into());}
        let vals=decode_rle_bp(&data[*offset..*offset+len], bw, count)?; *offset+=len;
        Ok(vals.iter().map(|v|*v as i32).collect())
    } else if encoding==4 { // BIT_PACKED
        let byte_len=((count as u32*bw)+7)as usize/8;
