        3 => { for _ in 0..count { if *offset+12>data.len(){return Err("EOF plain int96".into());} let mut nb=[0u8;8]; nb.copy_from_slice(&data[*offset..*offset+8]); let nanos=u64::from_le_bytes(nb); let day=u32::from_le_bytes([data[*offset+8],data[*offset+9],data[*offset+10],data[*offset+11]]); out.push(PrimVal::Int96{nanos, julian_day: day}); *offset+=12; } }
        4 => { for _ in 0..count { if *offset+4>data.len(){return Err("EOF plain float".into());} out.push(PrimVal::F32(f32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]))); *offset+=4; } }
        5 => { for _ in 0..count { if *offset+8>data.len(){return Err("EOF plain double".into());} let mut b=[0u8;8]; b.copy_from_slice(&data[*offset..*offset+8]); out.push(PrimVal::F64(f64::from_le_bytes(b))); *offset+=8; } }
        6 => { for _ in 0..count { if *offset+4>data.len(){return Err("EOF plain byte array len".into());} let len=u32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]) as usize; *offset+=4; if *offset+len>data.len(){return Err("EOF plain byte array".into());} out.push(PrimVal::Bytes(data[*offset..*offset+len].to_vec())); *offset+=len; } }
