        _ => return Err(format!("Parquet error: unexpected parquet type: {}", physical)),
    }
    Ok(out)
}

// Delta binary packed
pub struct DeltaReader<'a> { data: &'a [u8], pos: usize }
impl<'a> DeltaReader<'a> {
    pub fn uvarint(&mut self) -> Result<u64,String> { let mut s=0; let mut r=0u64; loop{ if self.pos>=self.data.len(){return Err("EOF delta".into());} let b=self.data[self.pos]; self.pos+=1; r|=((b&0x7f) as u64)<<s; if b&0x80==0{break;} s+=7;} Ok(r) }
    pub fn zigzag(&mut self) -> Result<i64,String> { let n=self.uvarint()?; Ok(((n>>1) as i64) ^ -((n&1) as i64)) }
}

pub fn decode_delta_binary(data: &[u8], count: usize, offset: &mut usize) -> Result<Vec<i64>, String> {
    let mut r=DeltaReader{data, pos:*offset};
    if count==0 { return Ok(vec![]); }
    let block_size=r.uvarint()? as usize;
    let miniblocks_per_block=r.uvarint()? as usize;
    let total=r.uvarint()? as usize;
    let first=r.zigzag()?;
    let mut values=vec![first];
    if total==0 { *offset=r.pos; return Ok(vec![]); }
    if block_size==0 || miniblocks_per_block==0 { return Err("Parquet error: invalid delta binary packed header".into()); }
    let values_per_miniblock=block_size/miniblocks_per_block;
    let mut cur=first;
    while values.len()<total && values.len()<count {
        let min_delta=r.zigzag()?;
        if r.pos+miniblocks_per_block>data.len(){return Err("EOF delta bitwidths".into());}
        let bitwidths: Vec<u8>=data[r.pos..r.pos+miniblocks_per_block].to_vec(); r.pos+=miniblocks_per_block;
        for (mb, &bw) in bitwidths.iter().enumerate() {
            let _=mb;
            let nvals=values_per_miniblock;
            // decode packed unsigned ints
            let byte_len=((nvals as u32 * bw as u32)/8) as usize; // note if bw doesn't divide, floor - values packed contiguously
            // bit reading within this miniblock region
            let start=r.pos;
            let mut bitpos=0usize;
            for _ in 0..nvals {
                if values.len()>=total || values.len()>=count { break; }
                let mut v: u64=0;
                for i in 0..bw {
                    let byte_idx=start+ (bitpos/8); let bit=if byte_idx<data.len(){(data[byte_idx]>> (bitpos%8))&1}else{0};
                    v|= (bit as u64)<<i; bitpos+=1;
                }
                let delta=min_delta + v as i64; cur+=delta; values.push(cur);
            }
            r.pos=start+byte_len;
            // if bw*vals %8 !=0, byte_len calc above might be floor; adjust to ceil
            let need=((nvals * bw as usize)+7)/8; if start+need>r.pos { r.pos=start+need; }
            if values.len()>=total { break; }
        }
    }
    *offset=r.pos;
    Ok(values.into_iter().take(count).collect())
}

pub fn decode_values(physical: i32, type_length: i32, encoding: i32, data: &[u8], count: usize, dict: Option<&Vec<PrimVal>>, offset: &mut usize) -> Result<Vec<PrimVal>, String> {
    match encoding {
