use crate::metadata::ColumnMeta;
use crate::model::PrimVal;
use crate::thrift::{get, get_i64, Reader as TReader, TVal};
use std::io::Read;

#[derive(Debug, Clone)]
pub struct PageInfo {
    pub page_type: i32,
    pub encoding: i32,
    pub num_values: i64,
    pub uncompressed_size: i64,
    pub compressed_size: i64,
    pub header_len: usize,
}

#[derive(Debug, Clone)]
pub struct Entry { pub rep: i32, pub def: i32, pub value: Option<PrimVal> }

fn snappy_decompress(data: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    // Raw snappy block format
    let mut pos = 0usize;
    // varint uncompressed length
    let mut shift = 0u32; let mut len: usize = 0;
    loop {
        if pos >= data.len() { return Err("Parquet error: snappy decompress error".to_string()); }
        let b = data[pos]; pos += 1; len |= ((b & 0x7f) as usize) << shift;
        if b & 0x80 == 0 { break; }
        shift += 7;
    }
    if len != expected {
        // trust varint
    }
    let mut out: Vec<u8> = Vec::with_capacity(len);
    while pos < data.len() {
        let tag = data[pos]; pos += 1;
        match tag & 0x03 {
            0 => {
                let mut lit_len = (tag >> 2) as usize;
                if lit_len >= 60 {
                    let extra = lit_len - 59;
                    if pos + extra > data.len() { return Err("snappy error".to_string()); }
                    let mut v: usize = 0; for i in 0..extra { v |= (data[pos+i] as usize) << (8*i); }
                    pos += extra; lit_len = v;
                }
                lit_len += 1;
                if pos + lit_len > data.len() { return Err("snappy error".to_string()); }
                out.extend_from_slice(&data[pos..pos+lit_len]); pos += lit_len;
            }
            1 => {
                if pos >= data.len() { return Err("snappy error".to_string()); }
                let length = 4 + ((tag >> 2) & 0x7) as usize;
                let offset = (((tag >> 5) as usize) << 8) | data[pos] as usize; pos += 1;
                if offset == 0 || offset > out.len() { return Err("snappy offset error".to_string()); }
                for _ in 0..length { let b = out[out.len()-offset]; out.push(b); }
            }
            2 => {
                if pos + 2 > data.len() { return Err("snappy error".to_string()); }
                let length = 1 + (tag >> 2) as usize;
                let offset = u16::from_le_bytes([data[pos], data[pos+1]]) as usize; pos += 2;
                if offset == 0 || offset > out.len() { return Err("snappy offset error".to_string()); }
                for _ in 0..length { let b = out[out.len()-offset]; out.push(b); }
            }
            _ => {
                if pos + 4 > data.len() { return Err("snappy error".to_string()); }
                let length = 1 + (tag >> 2) as usize;
                let offset = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize; pos += 4;
                if offset == 0 || offset > out.len() { return Err("snappy offset error".to_string()); }
                for _ in 0..length { let b = out[out.len()-offset]; out.push(b); }
            }
        }
    }
    if out.len() != len { /* accept if close */ }
    Ok(out)
}

pub fn lz4_block_decompress(data: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let mut out: Vec<u8> = Vec::with_capacity(expected);
    let mut pos = 0usize;
    while pos < data.len() {
        let token = data[pos]; pos += 1;
        let mut lit_len = (token >> 4) as usize;
        if lit_len == 15 { loop { if pos>=data.len(){return Err("lz4 error".into());} let b=data[pos]; pos+=1; lit_len+=b as usize; if b!=255{break;} } }
        if pos+lit_len > data.len() { return Err("lz4 literals error".into()); }
        out.extend_from_slice(&data[pos..pos+lit_len]); pos+=lit_len;
        if pos >= data.len() { break; }
        if pos+2 > data.len() { return Err("lz4 offset error".into()); }
        let offset = u16::from_le_bytes([data[pos], data[pos+1]]) as usize; pos+=2;
        if offset==0 || offset>out.len() { return Err("lz4 offset invalid".into()); }
        let mut match_len = (token & 0x0f) as usize;
        if match_len==15 { loop { if pos>=data.len(){return Err("lz4 error".into());} let b=data[pos]; pos+=1; match_len+=b as usize; if b!=255{break;} } }
        match_len += 4;
        for _ in 0..match_len { let b=out[out.len()-offset]; out.push(b); }
    }
    Ok(out)
}

mod ffi {
    #[link(name = ":libzstd.so.1")]
    extern "C" {
        pub fn ZSTD_decompress(dst: *mut u8, dst_capacity: usize, src: *const u8, src_size: usize) -> usize;
        pub fn ZSTD_isError(code: usize) -> u32;
    }
    #[link(name = ":libbrotlienc.so.1")]
    extern "C" {}
    #[link(name = ":libbrotlidec.so.1")]
    extern "C" {
        pub fn BrotliDecoderDecompress(encoded_size: usize, encoded_buffer: *const u8, decoded_size: *mut usize, decoded_buffer: *mut u8) -> i32;
    }
}

pub fn decompress(codec: i32, data: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    match codec {
        0 => Ok(data.to_vec()),
        1 => snappy_decompress(data, expected),
        2 => {
            let mut dec = flate2::read::GzDecoder::new(data);
            let mut out = Vec::with_capacity(expected);
            dec.read_to_end(&mut out).map_err(|e| format!("Parquet error: {}", e))?;
            Ok(out)
        }
        4 => {
            let mut out = vec![0u8; expected];
            let mut out_len = expected;
            let rc = unsafe { ffi::BrotliDecoderDecompress(data.len(), data.as_ptr(), &mut out_len, out.as_mut_ptr()) };
            if rc != 1 { return Err("Parquet error: brotli decompress failed".to_string()); }
            out.truncate(out_len); Ok(out)
        }
        5 => {
            // Parquet LZ4 (legacy): try raw block; if data has Hadoop framing, fallback handling
            // Hadoop LZ4: first 8 bytes? Actually try direct raw first
            if let Ok(v) = lz4_block_decompress(data, expected) { if v.len()==expected { return Ok(v); } }
            // Try skipping possible length prefixes
            for skip in [4usize, 8] {
                if data.len()>skip { if let Ok(v)=lz4_block_decompress(&data[skip..], expected) { if v.len()==expected { return Ok(v); } } }
            }
            // Try with liblz4 frame? fallback return raw attempt error
            lz4_block_decompress(data, expected)
        }
        6 => {
            let mut out = vec![0u8; expected];
            let n = unsafe { ffi::ZSTD_decompress(out.as_mut_ptr(), expected, data.as_ptr(), data.len()) };
            if unsafe { ffi::ZSTD_isError(n) } != 0 { return Err("Parquet error: zstd decompress failed".to_string()); }
            out.truncate(n); Ok(out)
        }
        7 => lz4_block_decompress(data, expected),
        3 => Err("Parquet error: LZO codec not supported".to_string()),
        _ => Err(format!("Parquet error: unsupported codec {}", codec)),
    }
}

pub fn parse_page_header(data: &[u8], offset: usize) -> Result<(PageInfo, usize, Option<(i32,i32)>, Option<(i64,i64)>), String> {
    // returns pageinfo, header_len, (def_enc, rep_enc) for v1, v2 extra (def_len, rep_len) via compressed field packing? We'll encode in separate return
    let mut r = TReader::new(&data[offset..]);
    let hdr = r.read_struct()?;
    let header_len = r.pos;
    let page_type = get_i64(&hdr, 1).unwrap_or(0) as i32;
    let uncomp = get_i64(&hdr, 2).unwrap_or(0);
    let comp = get_i64(&hdr, 3).unwrap_or(0);
    if uncomp < 0 || comp < 0 {
        return Err("parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted".to_string());
    }
    let mut encoding = 0i32; let mut num_values = 0i64; let mut extra = None; let mut v2 = None;
    if page_type == 0 {
        if let Some(TVal::Struct(dp)) = get(&hdr, 5) {
            num_values = get_i64(dp, 1).unwrap_or(0); encoding = get_i64(dp, 2).unwrap_or(0) as i32;
            extra = Some((get_i64(dp, 3).unwrap_or(3) as i32, get_i64(dp, 4).unwrap_or(3) as i32));
        }
    } else if page_type == 2 {
        if let Some(TVal::Struct(dp)) = get(&hdr, 7) { num_values = get_i64(dp, 1).unwrap_or(0); encoding = get_i64(dp, 2).unwrap_or(0) as i32; }
    } else if page_type == 3 {
        if let Some(TVal::Struct(dp)) = get(&hdr, 8) {
            num_values = get_i64(dp, 1).unwrap_or(0); encoding = get_i64(dp, 4).unwrap_or(0) as i32;
            let def_len = get_i64(dp, 5).unwrap_or(0); let rep_len = get_i64(dp, 6).unwrap_or(0);
            let is_comp = match get(dp, 7) { Some(TVal::Bool(b)) => *b, _ => true };
            v2 = Some((def_len, rep_len, is_comp as i64));
            // store v2 info in extra via encoding fields hack: return via Option second tuple repurposed below
            // We'll pass v2 through PageInfo by encoding extra in compressed field? Instead caller reconstructs by reparse - simplify: store in static? We'll return v2 in the 4th return as (def_len, rep_len) and is_comp via sign
            let _ = v2;
            return Ok((PageInfo { page_type, encoding, num_values, uncompressed_size: uncomp, compressed_size: comp, header_len }, header_len, extra, Some((def_len, rep_len))));
        }
    } else {
        // index page etc
        num_values = 0;
    }
    Ok((PageInfo { page_type, encoding, num_values, uncompressed_size: uncomp, compressed_size: comp, header_len }, header_len, extra, None))
}

pub fn iter_pages(file: &[u8], meta: &ColumnMeta) -> Result<Vec<PageInfo>, String> {
    let mut pages = Vec::new();
    let mut offset = meta.dict_page_offset.unwrap_or(meta.data_page_offset) as usize;
    let total = meta.total_compressed;
    if total < 0 { return Err("parquet: File out of specification: Number must be zero or positive: out of range integral type conversion attempted".to_string()); }
    let end_limit = offset.checked_add(total as usize).ok_or("overflow")?;
    let mut consumed: usize = 0;
    while (consumed as i64) < total {
        if offset >= file.len() { return Err("EOF: Parquet file too small".to_string()); }
        let (info, hlen, _, _) = parse_page_header(file, offset)?;
        let page_total = hlen.checked_add(info.compressed_size as usize).ok_or("overflow")?;
        if offset + page_total > end_limit || offset + page_total > file.len() {
            return Err("parquet: File out of specification: The page header reported the wrong page size".to_string());
        }
        consumed += page_total;
        offset += page_total;
        pages.push(info);
    }
    Ok(pages)
}

fn bits_needed(max: i32) -> u32 {
    if max <= 0 { 0 } else { 32 - ((max as u32).leading_zeros()) }
    // actually bits needed to represent max: e.g., max=1 ->1, max=3->2
}

pub struct RleDecoder<'a> { data: &'a [u8], pos: usize, bit_pos: usize }
impl<'a> RleDecoder<'a> {
    pub fn new(data: &'a [u8]) -> Self { Self { data, pos: 0, bit_pos: 0 } }
    fn read_varint(&mut self) -> Result<u64, String> {
        let mut shift=0; let mut result=0u64;
        loop { if self.pos>=self.data.len(){return Err("EOF rle".into());} let b=self.data[self.pos]; self.pos+=1; result|=((b&0x7f) as u64)<<shift; if b&0x80==0{break;} shift+=7; }
        Ok(result)
    }
    fn read_bit(&mut self) -> u32 {
        if self.pos>=self.data.len(){return 0;}
        let byte=self.data[self.pos]; let bit=((byte>>self.bit_pos)&1) as u32; self.bit_pos+=1; if self.bit_pos==8{self.bit_pos=0; self.pos+=1;} bit
    }
    fn read_bits(&mut self, bw: u32) -> u64 { let mut v=0u64; for i in 0..bw { v |= (self.read_bit() as u64) << i; } v }
}

pub fn decode_rle_bp(data: &[u8], bit_width: u32, count: usize) -> Result<Vec<i64>, String> {
    let mut dec = RleDecoder::new(data);
    let mut out = Vec::with_capacity(count);
    while out.len() < count {
        let header = dec.read_varint()?;
        if header & 1 == 0 {
            let run = (header >> 1) as usize;
            let byte_len = ((bit_width + 7) / 8) as usize;
            let mut v: u64 = 0;
            if dec.bit_pos!=0 { dec.pos+=1; dec.bit_pos=0; }
            for i in 0..byte_len { if dec.pos>=data.len(){return Err("EOF rle run".into());} v |= (data[dec.pos] as u64) << (8*i); dec.pos+=1; }
            for _ in 0..run { if out.len()>=count{break;} out.push(v as i64); }
        } else {
            let groups = (header >> 1) as usize;
            let total = groups * 8;
            for _ in 0..total { if out.len()>=count{ /* still need consume bits */ } let v=dec.read_bits(bit_width); if out.len()<count { out.push(v as i64); } }
            // align to byte boundary (read_bits already ends on byte if total* bw multiple of 8? groups*8*bw is divisible by 8 if bw integer, yes if bw>0)
            if dec.bit_pos!=0 { dec.pos+=1; dec.bit_pos=0; }
        }
    }
    Ok(out)
}

pub fn decode_bit_packed_msb(data: &[u8], bit_width: u32, count: usize) -> Vec<i64> {
    let mut out=Vec::with_capacity(count);
    if bit_width==0 { return vec![0; count]; }
    let mut bit_pos=0usize;
    for _ in 0..count {
        let mut v: u64=0;
        for _ in 0..bit_width {
            let byte_idx=bit_pos/8; let bit_in_byte=7-(bit_pos%8);
            let bit = if byte_idx<data.len() { (data[byte_idx]>>bit_in_byte)&1 } else {0};
            v=(v<<1)|(bit as u64); bit_pos+=1;
        }
        out.push(v as i64);
    }
    out
}

pub fn decode_levels(data: &[u8], max_level: i32, count: usize, encoding: i32, is_v2: bool, offset: &mut usize) -> Result<Vec<i32>, String> {
    if max_level==0 { return Ok(vec![0; count]); }
    let bw=bits_needed(max_level);
    if is_v2 {
        // data slice already is exactly the levels bytes; caller passes sub-slice and offset ignored
        let vals=decode_rle_bp(data, bw, count)?;
        return Ok(vals.iter().map(|v|*v as i32).collect());
    }
    if encoding==3 { // RLE
        if *offset+4>data.len(){return Err("EOF levels".into());}
        let len=u32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]) as usize; *offset+=4;
        if *offset+len>data.len(){return Err("EOF levels data".into());}
        let vals=decode_rle_bp(&data[*offset..*offset+len], bw, count)?; *offset+=len;
        Ok(vals.iter().map(|v|*v as i32).collect())
    } else if encoding==4 { // BIT_PACKED
        let byte_len=((count as u32*bw)+7)as usize/8;
        if *offset+byte_len>data.len(){return Err("EOF levels".into());}
        let vals=decode_bit_packed_msb(&data[*offset..*offset+byte_len], bw, count); *offset+=byte_len;
        Ok(vals)
    } else {
        // treat as RLE with length
        if *offset+4<=data.len(){
            let len=u32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]) as usize;
            if *offset+4+len<=data.len(){ let vals=decode_rle_bp(&data[*offset+4..*offset+4+len], bw, count)?; *offset+=4+len; return Ok(vals.iter().map(|v|*v as i32).collect()); }
        }
        let vals=decode_rle_bp(&data[*offset..], bw, count)?; Ok(vals.iter().map(|v|*v as i32).collect())
    }
}

pub fn decode_plain(physical: i32, type_length: i32, data: &[u8], count: usize, offset: &mut usize) -> Result<Vec<PrimVal>, String> {
    let mut out=Vec::with_capacity(count);
    match physical {
        0 => {
            // boolean LSB bits
            let mut bitpos=0usize; let start=*offset;
            for _ in 0..count { let byte=data.get(start+bitpos/8).copied().unwrap_or(0); let bit=(byte>>(bitpos%8))&1; out.push(PrimVal::Bool(bit!=0)); bitpos+=1; }
            *offset=start+(bitpos+7)/8;
        }
        1 => { for _ in 0..count { if *offset+4>data.len(){return Err("EOF plain int32".into());} out.push(PrimVal::I32(i32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]))); *offset+=4; } }
        2 => { for _ in 0..count { if *offset+8>data.len(){return Err("EOF plain int64".into());} let mut b=[0u8;8]; b.copy_from_slice(&data[*offset..*offset+8]); out.push(PrimVal::I64(i64::from_le_bytes(b))); *offset+=8; } }
        3 => { for _ in 0..count { if *offset+12>data.len(){return Err("EOF plain int96".into());} let mut nb=[0u8;8]; nb.copy_from_slice(&data[*offset..*offset+8]); let nanos=u64::from_le_bytes(nb); let day=u32::from_le_bytes([data[*offset+8],data[*offset+9],data[*offset+10],data[*offset+11]]); out.push(PrimVal::Int96{nanos, julian_day: day}); *offset+=12; } }
        4 => { for _ in 0..count { if *offset+4>data.len(){return Err("EOF plain float".into());} out.push(PrimVal::F32(f32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]))); *offset+=4; } }
        5 => { for _ in 0..count { if *offset+8>data.len(){return Err("EOF plain double".into());} let mut b=[0u8;8]; b.copy_from_slice(&data[*offset..*offset+8]); out.push(PrimVal::F64(f64::from_le_bytes(b))); *offset+=8; } }
        6 => { for _ in 0..count { if *offset+4>data.len(){return Err("EOF plain byte array len".into());} let len=u32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]) as usize; *offset+=4; if *offset+len>data.len(){return Err("EOF plain byte array".into());} out.push(PrimVal::Bytes(data[*offset..*offset+len].to_vec())); *offset+=len; } }
        7 => { let len=type_length as usize; for _ in 0..count { if *offset+len>data.len(){return Err("EOF plain fixed".into());} out.push(PrimVal::Bytes(data[*offset..*offset+len].to_vec())); *offset+=len; } }
        _ => return Err(format!("Parquet error: unexpected parquet type: {}", physical)),
    }
    Ok(out)
}

// Delta binary packed
pub struct DeltaReader<'a> { data: &'a [u8], pos: usize }
impl<'a> DeltaReader<'a> {
    pub fn uvarint(&mut self) -> Result<u64,String> { let mut s=0; let mut r=0u64; loop{ if self.pos>=self.data.len(){return Err("EOF delta".into());} let b=self.data[self.pos]; self.pos+=1; r|=((b&0x7f) as u64)<<s; if b&0x80==0{break;} s+=7;} Ok(r) }
    pub fn zigzag(&mut self) -> Result<i64,String> { let n=self.uvarint()?; Ok(((n>>1) as i64) ^ -((n&1) as i64)) }
}

pub fn decode_delta_binary(data: &[u8], count: usize, offset: &mut usize) -> Result<Vec<i64>, String> {
    let mut r=DeltaReader{data, pos:*offset};
    if count==0 { return Ok(vec![]); }
    let block_size=r.uvarint()? as usize;
    let miniblocks_per_block=r.uvarint()? as usize;
    let total=r.uvarint()? as usize;
    let first=r.zigzag()?;
    let mut values=vec![first];
    if total==0 { *offset=r.pos; return Ok(vec![]); }
    if block_size==0 || miniblocks_per_block==0 { return Err("Parquet error: invalid delta binary packed header".into()); }
    let values_per_miniblock=block_size/miniblocks_per_block;
    let mut cur=first;
    while values.len()<total && values.len()<count {
        let min_delta=r.zigzag()?;
        if r.pos+miniblocks_per_block>data.len(){return Err("EOF delta bitwidths".into());}
        let bitwidths: Vec<u8>=data[r.pos..r.pos+miniblocks_per_block].to_vec(); r.pos+=miniblocks_per_block;
        for (mb, &bw) in bitwidths.iter().enumerate() {
            let _=mb;
            let nvals=values_per_miniblock;
            // decode packed unsigned ints
            let byte_len=((nvals as u32 * bw as u32)/8) as usize; // note if bw doesn't divide, floor - values packed contiguously
            // bit reading within this miniblock region
            let start=r.pos;
            let mut bitpos=0usize;
            for _ in 0..nvals {
                if values.len()>=total || values.len()>=count { break; }
                let mut v: u64=0;
                for i in 0..bw {
                    let byte_idx=start+ (bitpos/8); let bit=if byte_idx<data.len(){(data[byte_idx]>> (bitpos%8))&1}else{0};
                    v|= (bit as u64)<<i; bitpos+=1;
                }
                let delta=min_delta + v as i64; cur+=delta; values.push(cur);
            }
            r.pos=start+byte_len;
            // if bw*vals %8 !=0, byte_len calc above might be floor; adjust to ceil
            let need=((nvals * bw as usize)+7)/8; if start+need>r.pos { r.pos=start+need; }
            if values.len()>=total { break; }
        }
    }
    *offset=r.pos;
    Ok(values.into_iter().take(count).collect())
}

pub fn decode_values(physical: i32, type_length: i32, encoding: i32, data: &[u8], count: usize, dict: Option<&Vec<PrimVal>>, offset: &mut usize) -> Result<Vec<PrimVal>, String> {
    match encoding {
        0 => decode_plain(physical, type_length, data, count, offset),
        2 | 8 => {
            // dictionary indices
            if count==0 { return Ok(vec![]); }
            if *offset>=data.len(){return Err("EOF dict indices".into());}
            let bw=data[*offset] as u32; *offset+=1;
            let indices=decode_rle_bp(&data[*offset..], bw, count)?;
            let dict=dict.ok_or("Parquet error: dictionary page missing")?;
            let mut out=Vec::with_capacity(count);
            for idx in indices { let v=dict.get(idx as usize).ok_or("Parquet error: dictionary index out of bounds")?; out.push(v.clone()); }
            Ok(out)
        }
        3 => {
            // RLE: for boolean, length-prefixed; in V2 caller passes slice without prefix? Detect: caller handles offset at start; we assume data[offset..] starts with 4-byte len if remaining sufficient and it's V1.
            // This function is used for data values where offset is at start of RLE payload. Try length prefix first if physical boolean and not v2 (caller may adjust)
            // We'll implement generic: first 4 bytes len
            if physical==0 {
                // caller distinguishes v1/v2 via encoding path - here we need to know. We'll attempt: if offset+4 <= len, read len and decode from that slice
                // V2 path will call decode_rle_values directly, not this.
                if *offset+4>data.len(){return Err("EOF rle".into());}
                let len=u32::from_le_bytes([data[*offset],data[*offset+1],data[*offset+2],data[*offset+3]]) as usize; *offset+=4;
                let vals=decode_rle_bp(&data[*offset..*offset+len], 1, count)?; *offset+=len;
                return Ok(vals.iter().map(|v|PrimVal::Bool(*v!=0)).collect());
            }
            // RLE for integers (dict fallback?) - decode as ints with bit width?? not expected
            let vals=decode_rle_bp(&data[*offset..], bits_needed(127), count)?;
            Ok(vals.iter().map(|v|PrimVal::I64(*v)).collect())
        }
        4 => {
            // BIT_PACKED deprecated: for integers, bit width needed for max? unknown; treat as levels style for int32 with bitwidth based on? not common for data
            Err("Parquet error: BIT_PACKED data encoding not supported".into())
        }
        5 => {
            let vals=decode_delta_binary(data, count, offset)?;
            Ok(vals.iter().map(|v| match physical { 1 => PrimVal::I32(*v as i32), _ => PrimVal::I64(*v) }).collect())
        }
        6 => {
            let lengths=decode_delta_binary(data, count, offset)?;
            let mut out=Vec::with_capacity(count);
            for len in lengths { let l=len as usize; if *offset+l>data.len(){return Err("EOF delta length byte array".into());} out.push(PrimVal::Bytes(data[*offset..*offset+l].to_vec())); *offset+=l; }
            Ok(out)
        }
        7 => {
            let prefix_lens=decode_delta_binary(data, count, offset)?;
            // suffixes are delta-length encoded: lengths then bytes starting at current offset
            let suffix_lens=decode_delta_binary(data, count, offset)?;
            let mut suffixes=Vec::with_capacity(count);
            for len in &suffix_lens { let l=*len as usize; if *offset+l>data.len(){return Err("EOF delta byte array suffix".into());} suffixes.push(data[*offset..*offset+l].to_vec()); *offset+=l; }
            let mut out: Vec<PrimVal>=Vec::with_capacity(count);
            let mut prev: Vec<u8>=Vec::new();
            for i in 0..count {
                let plen=prefix_lens[i] as usize;
                let mut v=prev.iter().take(plen).cloned().collect::<Vec<u8>>();
                v.extend_from_slice(&suffixes[i]);
                prev=v.clone(); out.push(PrimVal::Bytes(v));
            }
            Ok(out)
        }
        9 => {
            // BYTE_STREAM_SPLIT
            let width=match physical {4=>4,5=>8,1=>4,2=>8,7=>type_length as usize, _=> return Err("Parquet error: byte stream split unsupported type".into())};
            if width==0 { return Err("Parquet error: byte stream split width 0".into()); }
            let total_bytes=width*count;
            if *offset+total_bytes>data.len(){return Err("EOF byte stream split".into());}
            let mut vals=Vec::with_capacity(count);
            for i in 0..count {
                let mut bytes=vec![0u8; width];
                for j in 0..width { bytes[j]=data[*offset + j*count + i]; }
                // decode as plain from these bytes
                let mut off=0; let v=decode_plain(physical, type_length, &bytes, 1, &mut off)?; vals.push(v.into_iter().next().unwrap());
            }
            *offset+=total_bytes;
            Ok(vals)
        }
        _ => Err(format!("Parquet error: unsupported encoding {}", encoding)),
    }
}

pub fn decode_column(file: &[u8], meta: &ColumnMeta, physical: i32, type_length: i32, max_def: i32, max_rep: i32) -> Result<Vec<Entry>, String> {
    let pages=iter_pages(file, meta)?;
    let mut entries: Vec<Entry>=Vec::new();
    let mut dict: Option<Vec<PrimVal>>=None;
    let mut offset = meta.dict_page_offset.unwrap_or(meta.data_page_offset) as usize;
    for page in &pages {
        let data_start=offset+page.header_len;
        let comp_data=&file[data_start..data_start+page.compressed_size as usize];
        if page.page_type==2 {
            // dictionary page
            let buf=decompress(meta.codec, comp_data, page.uncompressed_size as usize)?;
            let mut off=0;
            let vals=decode_plain(physical, type_length, &buf, page.num_values as usize, &mut off)?;
            dict=Some(vals);
            offset+=page.header_len+page.compressed_size as usize;
            continue;
        }
        if page.page_type==1 { offset+=page.header_len+page.compressed_size as usize; continue; }
        if page.page_type==0 {
            // re-parse header to get def/rep encodings
            let (_, _, enc_pair, _) = parse_page_header(file, offset)?;
            let (def_enc, rep_enc)=enc_pair.unwrap_or((3,3));
            let buf=decompress(meta.codec, comp_data, page.uncompressed_size as usize)?;
            let mut off=0usize;
            let reps=if max_rep>0 { decode_levels(&buf, max_rep, page.num_values as usize, rep_enc, false, &mut off)? } else { vec![0; page.num_values as usize] };
            let defs=if max_def>0 { decode_levels(&buf, max_def, page.num_values as usize, def_enc, false, &mut off)? } else { vec![0; page.num_values as usize] };
            let non_null=defs.iter().filter(|d|**d==max_def).count();
            // special case: if max_def==0 non_null = num_values (above filter counts all zero==0 ok)
            let mut values=if page.encoding==3 && physical==0 {
                // V1 RLE boolean already handled in decode_values
                decode_values(physical, type_length, page.encoding, &buf, non_null, dict.as_ref(), &mut off)?
            } else {
                decode_values(physical, type_length, page.encoding, &buf, non_null, dict.as_ref(), &mut off)?
            };
            let mut vi=0usize;
            for i in 0..page.num_values as usize {
                let def=defs[i]; let val=if def==max_def { let v=values.get(vi).cloned(); vi+=1; v } else { None };
                entries.push(Entry{rep: reps[i], def, value: val});
            }
            let _=values;
        } else if page.page_type==3 {
            let (_, _, _, v2extra)=parse_page_header(file, offset)?;
            let (def_len, rep_len)=v2extra.unwrap_or((0,0));
            // comp_data layout: rep levels (rep_len), def levels (def_len), compressed values rest
            let rep_len_us=rep_len as usize; let def_len_us=def_len as usize;
            if comp_data.len()<rep_len_us+def_len_us { return Err("EOF data page v2 levels".into()); }
            let rep_data=&comp_data[0..rep_len_us];
            let def_data=&comp_data[rep_len_us..rep_len_us+def_len_us];
            let values_comp=&comp_data[rep_len_us+def_len_us..];
            // is_compressed flag: reparse
            let is_compressed = {
                let mut r=TReader::new(&file[offset..]); let hdr=r.read_struct()?; let mut ic=true; if let Some(TVal::Struct(dp))=get(&hdr,8){ if let Some(TVal::Bool(b))=get(dp,7){ ic=*b; } } ic
            };
            let values_buf=if is_compressed && meta.codec!=0 { decompress(meta.codec, values_comp, (page.uncompressed_size as usize).saturating_sub(rep_len_us+def_len_us))? } else { values_comp.to_vec() };
            let reps=if max_rep>0 { let mut o=0; decode_levels(rep_data, max_rep, page.num_values as usize, 3, true, &mut o)? } else { vec![0; page.num_values as usize] };
            let defs=if max_def>0 { let mut o=0; decode_levels(def_data, max_def, page.num_values as usize, 3, true, &mut o)? } else { vec![0; page.num_values as usize] };
            let non_null=defs.iter().filter(|d|**d==max_def).count();
            let mut off=0usize;
            let values=if page.encoding==3 && physical==0 {
                // RLE in V2: no length prefix, decode directly from values_buf
                let vals=decode_rle_bp(&values_buf, 1, non_null)?;
                vals.iter().map(|v|PrimVal::Bool(*v!=0)).collect::<Vec<_>>()
            } else if page.encoding==3 {
                // RLE encoded integers? decode rle bp based data
                decode_values(physical, type_length, page.encoding, &values_buf, non_null, dict.as_ref(), &mut off)?
            } else {
                decode_values(physical, type_length, page.encoding, &values_buf, non_null, dict.as_ref(), &mut off)?
            };
            let mut vi=0usize;
            for i in 0..page.num_values as usize {
                let def=defs[i]; let val=if def==max_def { let v=values.get(vi).cloned(); vi+=1; v } else { None };
                entries.push(Entry{rep: reps[i], def, value: val});
            }
        }
        offset+=page.header_len+page.compressed_size as usize;
    }
    Ok(entries)
}
