pub fn load_dataset(file_bytes: &[u8], meta: &FileMeta) -> Result<Dataset, String> {
    let tree = build_tree(&meta.schema)?;
    let leaves = compute_leaves(&tree);
    let builder = VBuilder { tree: &tree };
    let columns = builder.build_root_columns();

    // Precompute steps per top column per leaf in that column
    let mut col_steps: Vec<Vec<(usize, Vec<Step>)>> = Vec::new();
    for (_, vnode) in &columns {
        let mut v = Vec::new();
        for leaf in vnode.leaves() { if let Some(s) = steps_for_leaf(vnode, leaf) { v.push((leaf, s)); } }
        col_steps.push(v);
    }

    let mut all_column_strs: Vec<Vec<String>> = vec![Vec::new(); columns.len()];
    let mut total_rows: usize = 0;

    for rg in &meta.row_groups {
        // decode each leaf
        let mut leaf_entries: Vec<Vec<Entry>> = Vec::with_capacity(leaves.len());
        for (li, leaf) in leaves.iter().enumerate() {
            // find column chunk: by index li if counts match, else by path
            let chunk = if rg.columns.len() == leaves.len() { rg.columns.get(li) } else { rg.columns.iter().find(|c| c.meta.as_ref().map(|m| m.path == leaf.path).unwrap_or(false)) };
            let chunk = chunk.ok_or_else(|| "Parquet error: column chunk not found".to_string())?;
            let col_meta = chunk.meta.as_ref().ok_or_else(|| "Parquet error: column metadata missing".to_string())?;
