use crate::metadata::FileMeta;
use crate::model::{format_top, Value};
use crate::reader::{decode_column, Entry};
use crate::schema::{build_tree, PrimKind, SchemaTree, VBuilder, VNode};
use crate::schema::convert_prim;

#[derive(Debug, Clone)]
pub struct LeafInfo {
    pub node_idx: usize,
    pub path: Vec<String>,
    pub max_def: i32,
    pub max_rep: i32,
    pub physical: i32,
    pub type_length: i32,
}

#[derive(Debug)]
pub struct Dataset {
    pub tree: SchemaTree,
    pub columns: Vec<(String, VNode)>,
    pub column_strs: Vec<Vec<String>>, // per top column per row, formatted & truncated
    pub num_rows: usize,
    pub leaves: Vec<LeafInfo>,
}

pub fn compute_leaves(tree: &SchemaTree) -> Vec<LeafInfo> {
    let mut out = Vec::new();
    fn rec(tree: &SchemaTree, idx: usize, path: Vec<String>, cum_def: i32, cum_rep: i32, out: &mut Vec<LeafInfo>) {
        let node = &tree.nodes[idx];
        let mut def = cum_def; let mut rep = cum_rep;
        if idx != tree.root {
            match node.el.repetition { Some(1) | Some(2) => def += 1, _ => {} }
            if node.el.repetition == Some(2) { rep += 1; }
        }
        let mut p = path.clone();
        if idx != tree.root { p.push(node.el.name.clone()); }
        if let Some(_leaf) = node.leaf_index {
            out.push(LeafInfo { node_idx: idx, path: p, max_def: def, max_rep: rep, physical: node.el.physical_type.unwrap_or(0), type_length: node.el.type_length.unwrap_or(0) });
            return;
        }
        for &c in &node.children { rec(tree, c, p.clone(), def, rep, out); }
    }
    rec(tree, tree.root, vec![], 0, 0, &mut out);
    out
}

// Partial assembly tree
#[derive(Debug, Clone)]
enum Partial { Unknown, Null, List(Vec<Partial>), Struct(Vec<Partial>), Value(Value) }

#[derive(Debug, Clone)]
enum Step {
    Struct { present_def: i32, num_fields: usize, field_idx: usize },
    List { empty_def: i32, elem_def: i32, rep_level: i32 },
    Prim { max_def: i32, kind: PrimKind, leaf: usize },
}

fn steps_for_leaf(node: &VNode, leaf: usize) -> Option<Vec<Step>> {
    match node {
        VNode::Prim { leaf: l, kind, max_def } => {
            if *l == leaf { Some(vec![Step::Prim { max_def: *max_def, kind: kind.clone(), leaf }]) } else { None }
        }
        VNode::Struct { fields, present_def } => {
            for (i, (_, f)) in fields.iter().enumerate() {
                if let Some(mut sub) = steps_for_leaf(f, leaf) {
                    let mut v = vec![Step::Struct { present_def: *present_def, num_fields: fields.len(), field_idx: i }];
                    v.append(&mut sub); return Some(v);
                }
            }
            None
        }
        VNode::List { elem, empty_def, elem_def, rep_level } => {
            if let Some(mut sub) = steps_for_leaf(elem, leaf) {
                let mut v = vec![Step::List { empty_def: *empty_def, elem_def: *elem_def, rep_level: *rep_level }];
                v.append(&mut sub); return Some(v);
            }
            None
        }
    }
}

fn resolve(p: Partial) -> Value {
    match p {
        Partial::Unknown => Value::Null,
        Partial::Null => Value::Null,
        Partial::Value(v) => v,
        Partial::List(items) => Value::List(items.into_iter().map(resolve).collect()),
        Partial::Struct(fields) => Value::Struct(fields.into_iter().map(resolve).collect()),
    }
}

fn insert_entry(root: &mut Partial, steps: &[Step], entry: &Entry, counters: &mut Vec<Option<usize>>) {
    let mut cur: &mut Partial = root;
    for (pos, step) in steps.iter().enumerate() {
        match step {
            Step::Struct { present_def, num_fields, field_idx } => {
                if entry.def < *present_def { *cur = Partial::Null; return; }
                let fields = match cur {
                    Partial::Struct(f) => f,
                    _ => { *cur = Partial::Struct(vec![Partial::Unknown; *num_fields]); match cur { Partial::Struct(f) => f, _ => unreachable!() } }
                };
                cur = &mut fields[*field_idx];
            }
            Step::List { empty_def, elem_def, rep_level } => {
                if entry.def < *empty_def { *cur = Partial::Null; return; }
                if entry.def < *elem_def { *cur = Partial::List(vec![]); return; }
                if !matches!(cur, Partial::List(_)) { *cur = Partial::List(vec![]); }
                // decide index
                let idx: usize = if entry.rep < *rep_level {
                    counters[pos] = Some(0);
                    for c in counters.iter_mut().skip(pos+1) { *c = None; }
                    0
                } else if entry.rep == *rep_level {
                    match counters[pos] {
                        Some(i) => { counters[pos] = Some(i+1); for c in counters.iter_mut().skip(pos+1) { *c = None; } i+1 }
                        None => { counters[pos] = Some(0); 0 }
                    }
                } else {
                    match counters[pos] { Some(i) => i, None => { counters[pos] = Some(0); 0 } }
                };
                let items = match cur { Partial::List(v) => v, _ => unreachable!() };
                while items.len() <= idx { items.push(Partial::Unknown); }
                cur = &mut items[idx];
            }
            Step::Prim { max_def, kind, .. } => {
                if entry.def >= *max_def {
                    if let Some(pv) = &entry.value {
                        match convert_prim(pv, kind) { Ok(v) => *cur = Partial::Value(v), Err(_) => *cur = Partial::Null }
                    } else { *cur = Partial::Null; }
                } else { *cur = Partial::Null; }
                return;
            }
        }
    }
}

