use common::*;
use loader::Dataset;
use metadata::FileMeta;
use model::Value;
use ratatui::{buffer::Buffer, layout::Rect, style::{Color, Modifier, Style}, text::{Line, Span}, widgets::{Block, BorderType, Borders, Paragraph, Widget}};
use std::{collections::HashSet, io, path::Path};

const TAB_NAMES: [&str; 4] = ["Visualize", "Metadata", "Schema", "Row Groups"];

#[derive(Debug, Clone)]
pub struct TreeLineInfo {
    pub text: String,
    pub node_idx: usize,
    pub is_leaf: bool,
    pub is_root: bool,
}

pub struct App {
    pub path: String,
    pub meta: FileMeta,
    pub dataset: Dataset,
    pub file_bytes: Vec<u8>,
    pub tab: usize,
    pub selected_row: usize,
    pub row_scroll: usize,
