fn render(width: u16, maxw: Vec<u16>, headers: Vec<&str>, rows_data: Vec<Vec<&str>>) {
    let backend = TestBackend::new(width, 5);
    let mut term = Terminal::new(backend).unwrap();
    term.draw(|f| {
        let area = Rect{x:0,y:0,width,height:5};
        let widths: Vec<Constraint> = maxw.iter().map(|w| Constraint::Length(*w)).collect();
        let header = Row::new(headers.iter().map(|h| Cell::from(*h)).collect::<Vec<_>>());
        let rows = rows_data.iter().map(|r| Row::new(r.iter().map(|c| Cell::from(*c)).collect::<Vec<_>>()));
        let table = Table::new(rows, widths).header(header).column_spacing(1);
        f.render_widget(table, area);
    }).unwrap();
    let buf = term.backend().buffer().clone();
    println!("--- width {}", width);
    for y in 0..2 { let mut s=String::new(); for x in 0..width { s.push_str(buf[(x,y)].symbol()); } println!("{:?}", s); }
}
