import pathlib
p=pathlib.Path("src/main.rs"); t=p.read_text()
start=t.index("    draw_block(buf, right_rect, true, Style::default(), vec![(vec![span(\"Column Statistics\"")
end=t.index("fn draw_rowgroups")
old=t[start:end]
new='''    draw_block(buf, right_rect, true, Style::default(), vec![(vec![span("Column Statistics", Style::default().fg(Color::Indexed(2)).add_modifier(Modifier::BOLD))], 1)], vec![]);
    let inner_rect = Rect { x: right_rect.x + 1, y: right_rect.y + 1, width: right_rect.width.saturating_sub(2), height: right_rect.height.saturating_sub(2) };
    if inner_rect.height > 0 && inner_rect.width > 0 {
        let endc = std::cmp::min(headers.len(), app.stats_col_offset + app.stats_visible_cols);
        let col_idx: Vec<usize> = (app.stats_col_offset..endc).collect();
        let constraints: Vec<ratatui::layout::Constraint> = col_idx.iter().map(|&ci| ratatui::layout::Constraint::Length((widths[ci] + 1) as u16)).collect();
        let header_row = Row::new(col_idx.iter().map(|&ci| Cell::from(headers[ci])).collect::<Vec<_>>())
            .style(Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD));
        // rows starting at tree_scroll (stats row index = tree line -1; first displayed data row aligns with tree line scroll+1)
        let start_row = app.tree_scroll.min(rows.len());
        let mut table_rows: Vec<Row> = Vec::new();
        for (offset, r) in rows.iter().enumerate().skip(start_row) {
            let tree_line_idx = offset + 1;
            let is_selected = app.selected_leaf.map(|s| app.leaf_tree_line[s] == tree_line_idx).unwrap_or(false);
            let is_group = tree_line_idx < app.tree_lines.len() && !app.tree_lines[tree_line_idx].is_leaf;
            let cells: Vec<Cell> = col_idx.iter().map(|&ci| {
                let st = if is_selected { Style::default().fg(Color::Indexed(0)).bg(Color::Indexed(3)) } else if is_group { style_fg(2) } else { Style::default() };
                Cell::from(r[ci].clone()).style(st)
            }).collect();
            let mut row = Row::new(cells);
            if is_selected { row = row.style(Style::default().fg(Color::Indexed(0)).bg(Color::Indexed(3))); }
            table_rows.push(row);
        }
        let table = Table::new(table_rows, constraints).header(header_row).column_spacing(1);
        table.render(inner_rect, buf);
    }
}

