import struct

# thrift compact writer
def varint(n):
    out=bytearray()
    while True:
        b=n & 0x7f; n >>=7
        if n: out.append(b|0x80)
        else: out.append(b); break
    return bytes(out)
def zigzag(n): return varint((n<<1) ^ (n>>63) if n>=0 else ((-n<<1)-1) ) if False else varint((n*2) if n>=0 else (-n*2-1))

def enc_val(ctype, v):
    if ctype==1 or ctype==2: return b'' # bool in struct header
    if ctype in (4,5,6): return zigzag(v)
    if ctype==3: return bytes([v & 0xff])
