    out=bytearray(b'PAR1')
    row_groups=[]
    total_rows_sum=0
    for rg_cols in colspecs_per_rg:
        rg_start_cols=[]
        num_rows = rg_cols[0].num_rows if rg_cols and hasattr(rg_cols[0],'num_rows') else None
        # num_rows determined by caller via attribute on first spec or entries? We'll pass via a tuple elsewhere: use global?
        col_chunks=[]
        total_uncomp_rg=0; total_comp_rg=0
        for col in rg_cols:
            offset_start=len(out)
            header, comp_data, us, cs = build_column_page(col.entries, col.phys, col.max_def, col.type_len, col.codec)
            out.extend(header); out.extend(comp_data)
            total_page_uncomp=len(header)+us; total_page_comp=len(header)+cs
            total_uncomp_rg+=total_page_uncomp; total_comp_rg+=total_page_comp
            meta_fields=[(1,5,col.phys),(2,9,(5,[0,3])),(3,9,(8,[p.encode() if isinstance(p,str) else p for p in col.path])),(4,5,col.codec),(5,6,len(col.entries)),(6,6,total_page_uncomp),(7,6,total_page_comp),(9,6,offset_start)]
            if col.stats is not None:
                # stats: fields (fid,ctype,val) - 3 null,5 max bytes,6 min bytes
                meta_fields.append((12,12,col.stats))
            # file_offset in ColumnChunk = offset after col? mimic writers: end offset
            file_offset=offset_start+total_page_comp
            chunk_fields=[(2,6,file_offset),(3,12,meta_fields)]
            col_chunks.append(chunk_fields)
        # num_rows for rg: stored on ColSpec.rg_rows if set else infer? caller sets attribute on list? We'll use colspecs_per_rg rows param via global
        rg_rows = getattr(rg_cols, 'rows', None)
        if rg_rows is None: rg_rows = 0
        total_rows_sum+=rg_rows
        rg_fields=[(1,9,(12,col_chunks)),(2,6,total_uncomp_rg),(3,6,rg_rows),(6,6,total_comp_rg)]
        row_groups.append(rg_fields)
    if root_num_rows is None: root_num_rows=total_rows_sum
    footer_fields=[(1,5,version),(2,9,(12,schema_elements)),(3,6,root_num_rows),(4,9,(12,row_groups))]
    if created_by is not None: footer_fields.append((6,8,created_by.encode()))
    footer=enc_struct(footer_fields)
    out.extend(footer); out.extend(struct.pack('<I', len(footer))); out.extend(b'PAR1')
    open(path,'wb').write(out)
    return bytes(out)

# attach helper to make rg list with rows
class RGList(list):
    pass
def make_rg(cols, rows):
    r=RGList(cols); r.rows=rows; return r
