pub fn format_float64(v: f64, _is32: bool) -> String { fmt_float_bits(v, None) }

fn significant_digits(v: f64) -> usize {
    let s = format!("{}", v.abs());
    let mut digits: String = s.chars().filter(|c| c.is_ascii_digit()).collect();
    // strip leading zeros
    let trimmed = digits.trim_start_matches('0').to_string();
    digits = trimmed;
    // strip trailing zeros only if there was a decimal point in original (fraction trailing zeros are not significant in shortest repr, Rust already gives shortest)
    digits.chars().count()
}

fn fmt_float_bits(v: f64, f32v: Option<f32>) -> String {
    if v.is_nan() { return "NaN".to_string(); }
    if v.is_infinite() { return if v > 0.0 { "inf".to_string() } else { "-inf".to_string() }; }
    if v == 0.0 { return if v.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() }; }
    let av = v.abs();
    // Very large magnitude: fixed 4-decimal exponent
    if av >= 1e9 {
        return match f32v { Some(f) => format!("{:.4e}", f), None => format!("{:.4e}", v) };
    }
    if av < 1e-6 {
        // Use Rust display; if it's long, use .4e
        let disp = match f32v { Some(f) => format!("{}", f), None => format!("{}", v) };
        if disp.chars().count() > 9 {
            return match f32v { Some(f) => format!("{:.4e}", f), None => format!("{:.4e}", v) };
        } else {
            // disp like 0.0000005 -> keep (add .0 not needed as it has fractional)
            return disp;
        }
    }
    if av < 1e-5 {
        // Rust display gives full (e.g., 0.0000015)
        return match f32v { Some(f) => format!("{}", f), None => format!("{}", v) };
    }
    // Integer values
    if v.fract() == 0.0 {
        if av >= 999999.0 {
            return match f32v { Some(f) => format!("{:e}", f), None => format!("{:e}", v) };
        }
        // fall through to decimal formatting which adds .0
    } else if av >= 1_000_000.0 && significant_digits(v) > 8 {
        return match f32v { Some(f) => format!("{:.4e}", f), None => format!("{:.4e}", v) };
    }
    // Decimal: round to 6 decimal places, trim trailing zeros
    let mut s = match f32v { Some(f) => format!("{:.6}", f), None => format!("{:.6}", v) };
    if s.contains('.') {
        while s.ends_with('0') { s.pop(); }
        if s.ends_with('.') { s.push('0'); }
    }
    s
}

'''
