    if w == 0 || rect.width < 2 { return; }
    let y = if top { rect.y } else { rect.y + rect.height - 1 };
    let inner_w = (rect.width - 2) as usize;
    let area_x = rect.x + 1;
    // Flatten spans to chars with style
    let mut chars: Vec<(char, Style)> = Vec::new();
    for (s, st) in &spans { for ch in s.chars() { chars.push((ch, *st)); } }
    let (skip, offset) = if w > inner_w {
        match align { 1 => ((w - inner_w) / 2, 0), 2 => (w - inner_w, 0), _ => (0, 0) }
    } else {
