    };
    let mut x = area_x + offset as u16;
    for (ch, st) in chars.iter().skip(skip).take(inner_w) {
        if x >= rect.x + rect.width - 1 { break; }
        buf.set_string(x, y, ch.to_string(), *st);
        x += 1;
    }
}
