fn leaf_column_meta_agg(app: &App, leaf_idx: usize) -> (i64, i64, String, String, String, String, String) {
    let mut comp = 0i64; let mut uncomp = 0i64; let mut codec_set: HashSet<String> = HashSet::new(); let mut enc_set: HashSet<String> = HashSet::new();
    let mut nulls: i64 = 0;
    let mut min_bytes: Option<Vec<u8>> = None; let mut max_bytes: Option<Vec<u8>> = None;
    let mut physical = 0i32;
    if let Some(node_idx) = app.dataset.leaves.get(leaf_idx).map(|l| l.node_idx) { physical = app.dataset.tree.nodes[node_idx].el.physical_type.unwrap_or(0); }
    for rg in &app.meta.row_groups {
        if let Some(c) = rg.columns.get(leaf_idx) {
            if let Some(m) = &c.meta {
                comp += m.total_compressed; uncomp += m.total_uncompressed;
                codec_set.insert(metadata::codec_name(m.codec));
                for e in &m.encodings { enc_set.insert(metadata::encoding_name(*e).to_string()); }
                if let Some(s) = &m.statistics {
                    nulls += s.null_count.unwrap_or(0);
                    if let Some(mn) = s.min_bytes() {
                        let replace = match &min_bytes { None => true, Some(cur) => stat_value_cmp(mn, cur, physical) == std::cmp::Ordering::Less };
                        if replace { min_bytes = Some(mn.to_vec()); }
                    }
                    if let Some(mx) = s.max_bytes() {
                        let replace = match &max_bytes { None => true, Some(cur) => stat_value_cmp(mx, cur, physical) == std::cmp::Ordering::Greater };
                        if replace { max_bytes = Some(mx.to_vec()); }
                    }
                }
            }
        }
    }
    let enc = enc_set.iter().cloned().collect::<Vec<_>>().join(", ");
    let codec = codec_set.iter().cloned().collect::<Vec<_>>().join(", ");
    let min_s = format_schema_stat_fwd(min_bytes.as_deref(), physical);
    let max_s = format_schema_stat_fwd(max_bytes.as_deref(), physical);
    (comp, uncomp, codec, enc, min_s, max_s, format!("{}", nulls))
}

// Forward wrapper because format_schema_stat is defined below
fn format_schema_stat_fwd(bytes: Option<&[u8]>, physical: i32) -> String { format_schema_stat(bytes, physical) }

