        4 => { let av=if a.len()>=4{f32::from_le_bytes([a[0],a[1],a[2],a[3]]) as f64}else{0.0}; let bv=if b.len()>=4{f32::from_le_bytes([b[0],b[1],b[2],b[3]]) as f64}else{0.0}; av.partial_cmp(&bv).unwrap_or(Ordering::Equal) }
