import re, glob, sys
ENC=["PLAIN_DICTIONARY","DELTA_LENGTH_BYTE_ARRAY","DELTA_BINARY_PACKED","DELTA_BYTE_ARRAY","BYTE_STREAM_SPLIT","PLAIN","RLE_DICTIONARY","RLE","BIT_PACKED"]
# sort longest first for regex
pattern=re.compile(r'\b(?:' + '|'.join(ENC) + r')(?:, (?:' + '|'.join(ENC) + r'))*\b')
CODECS=["UNCOMPRESSED","SNAPPY","GZIP(GzipLevel(6))","ZSTD(ZstdLevel(1))","LZ4_RAW","LZ4","BROTLI","LZO"]
def norm(s):
    def repl(m):
        parts=m.group(0).split(", ")
        return ", ".join(sorted(parts))
    s=pattern.sub(repl, s)
    # codecs in metadata/schema: sequences with counts or comma
    # Metadata Codecs line: sort codec(count) tokens
    return s

def check(name):
    try:
        a=open(f"/tmp/cmp/{name}.oracle.txt").read().splitlines()
        b=open(f"/tmp/cmp/{name}.new.txt").read().splitlines()
    except: return
    diffs=[]
    for i,(x,y) in enumerate(zip(a,b)):
        if norm(x)!=norm(y): diffs.append((i,x,y))
    if len(a)!=len(b): diffs.append(("len",len(a),len(b)))
    if diffs:
        print(f"REALFAIL {name} ({len(diffs)} lines)")
        for i,x,y in diffs[:10]:
            print(" line",i); print(" -",x); print(" +",y)
    else:
        print(f"NORMPASS {name}")
for n in sys.argv[1:]: check(n)
