old_start = t.index("    // prepare stats rows")
old_end = t.index("    app.stats_visible_cols =")
old_block = t[old_start:old_end]
new_block = '''    // prepare stats rows (cached after first computation)
    let headers = ["Repetition", "Physical", "Compressed", "Uncompressed", "Ratio", "Encodings", "Compression", "Min", "Max", "Nulls"];
    if app.schema_cache.is_none() {
        let mut rows: Vec<Vec<String>> = Vec::new();
        for info in &app.tree_lines[1.min(app.tree_lines.len())..] {
            let node = &app.dataset.tree.nodes[info.node_idx];
            if info.is_leaf {
                let leaf_idx = node.leaf_index.unwrap();
                let (comp, uncomp, codec, enc, min_s, max_s, nulls) = leaf_column_meta_agg(app, leaf_idx);
                let ratio_str = if comp == 0 { "N/A".to_string() } else { format!("{:.2}x", uncomp as f64 / comp as f64) };
                rows.push(vec![
                    metadata::repetition_name(node.el.repetition).to_string(),
                    metadata::physical_name(node.el.physical_type.unwrap_or(0)).to_string(),
                    fmt_bytes_1(comp), fmt_bytes_1(uncomp), ratio_str, enc, codec, min_s, max_s, nulls,
                ]);
            } else {
                rows.push(vec![metadata::repetition_name(node.el.repetition).to_string(), "group".to_string(), "".into(), "".into(), "".into(), "".into(), "".into(), "".into(), "".into(), "".into()]);
            }
        }
        let mut widths: Vec<usize> = headers.iter().map(|h| text_width(h)).collect();
        for r in &rows { for (i, c) in r.iter().enumerate() { widths[i] = widths[i].max(text_width(c)); } }
        app.schema_cache = Some((rows, widths));
    }
    let (rows, widths) = app.schema_cache.as_ref().unwrap();
    let rows = rows.clone(); let widths = widths.clone();

'''
t=t[:old_start]+new_block+t[old_end:]
# Remove duplicated headers line if still present after old block (old block included header definition?) It defined headers - our new also defines. The old block until stats_visible includes headers + rows + widths. Good.
p.write_text(t)
print("ok")
PY
python3 /tmp/patch_cache.py
grep -n "let headers" src/main.rs | head
cargo build --offline 2>&1 | grep -E "^error" -A8 | head -n 40; echo DONE"}

